engineSystemTeaching["kv-cache"] = {
  intro: ["生成新 Token 时，注意力需要读取历史位置的 Key 和 Value。若每一步都重新计算全部历史，会重复大量工作；把这些向量保存下来，就是 KV Cache。代价是每条活跃请求都占用持续增长的存储。", "本课讲缓存怎样组织与共享。分页并没有改变注意力的数学含义，而是让逻辑连续的序列可以放在不连续的物理块里，并让可复用的前缀避免重复保存。"],
  prerequisites: [pre("Key / Value", "注意力中，Key 用于与当前查询计算匹配分数，Value 是按这些分数加权汇总的内容。缓存保存的是模型算出的向量，不是原始文本。", "llm-block"), pre("逻辑位置与物理位置", "逻辑位置是 Token 在序列里的编号；物理位置是它的 KV 在显存中的实际存储槽。映射表把二者连接起来。", "tensor-address"), pre("块", "缓存分配的固定容量单位。一块可以容纳若干个 Token 位置的 KV，未填满的尾块仍然占着整块容量。")],
  chapters: {
    address: section("序列位置先找到逻辑块，再找到物理块",
      p("对模型而言，历史位置按 0、1、2……排列；显存分配器却只需要找到可用块，不要求一条请求的所有块相邻。请求的块表记录‘第几个逻辑块放在哪个物理块’，注意力实现读取时再查这个映射。"),
      formula("分页地址分解", "<mrow><mi>b</mi><mo>=</mo><mo>⌊</mo><mfrac><mi>t</mi><mi>P</mi></mfrac><mo>⌋</mo><mo>,</mo><mi>o</mi><mo>=</mo><mi>t</mi><mo>mod</mo><mi>P</mi></mrow>", [["t", "从 0 开始的序列位置"], ["P", "每块容纳的位置数"], ["b", "逻辑块号"], ["o", "块内偏移"]], "先用整除找到所属块，再用余数找到块内位置；物理块号由这条请求自己的块表提供。", ["例如每块 4 个位置，位置 6 属于逻辑块 1，块内偏移 2。", "若块表把逻辑块 1 映射到物理块 7，就读取物理块 7 的第 2 号位置；不能把序列位置 6 直接当物理槽 6。"]),
      fig("沿同一个逻辑位置追踪到块表和物理槽。图中的连线表示实际映射，不表示所有块必须按顺序摆放。")),
    prefix: section("相同前缀为什么可以复用已算出的状态",
      p("因果注意力中，一个位置的表示取决于它自身和之前的上下文。同一模型、相同计算语义与相同前缀，可以产生可复用的前缀 KV；它们后面接的不同问题不会反过来改变已完成的因果前缀。共享的是这段已经算出的状态。"),
      p("例如多个请求包含完全相同的系统提示词，分配器可以让它们的块表指向同一组缓存块。这里要求的是 Token 与影响计算的条件匹配，不能只看两段文本读起来相似。具体缓存键、模型标识和其它输入条件需由实现保证。"),
      note("共享前缀并不让后续新增 Token 免费：每条请求仍有自己的后缀计算和独立生成进度。")),
    append: section("追加位置只扩展尾部，写共享块要特别处理",
      p("请求继续增长时，先填尾块的空槽；尾块满了，再分配一个块并追加到块表。已经存好的完整历史块可以留在原处，因而不必为了得到更长的连续数组而搬迁整段历史。"),
      p("若多个请求共享的块还会被修改，直接写入就会让一个请求改变另一个请求读到的内容。写时复制（Copy-on-Write）的思想是：在需要独立写入时先得到自己的副本，再追加。这与复用只读、已完成的完整前缀块是不同的情况；实际共享粒度和尾块策略由实现决定。")),
    release: section("请求结束与物理块可回收不是同一时刻",
      p("物理块可能被多条请求引用。引用计数记录还有多少使用者依赖它；一条请求结束，只能移除自己的引用。只有没有逻辑使用者、也没有在途计算继续读取时，块才适合重新分配。"),
      p("缓存系统还可能保留暂时无人使用的前缀块，等待后续请求命中；此时它可以进入可淘汰状态，而不必立即抹掉内容。区分‘仍在使用’、‘可复用但可淘汰’和‘已重新分配’，比只画一个释放按钮更接近缓存管理的含义。")),
    capacity: section("块越大，管理更粗；块越小，映射更细",
      formula("一条不共享请求的已分配容量", "<mrow><mi>C</mi><mo>=</mo><mo>⌈</mo><mfrac><mi>L</mi><mi>P</mi></mfrac><mo>⌉</mo><mi>P</mi><mo>,</mo><mi>U</mi><mo>=</mo><mi>C</mi><mo>−</mo><mi>L</mi></mrow>", [["L", "已需要存储 KV 的位置数"], ["P", "每块位置容量"], ["C", "按整块分配后的位置容量"], ["U", "已分配但未使用的位置数"]], "向上取整来自整块分配。尾部碎片是已经占有的空槽，不等于全局空闲块。", ["L=6、P=4 时，分配 2 块，容量 8，空着 2 个位置。", "P 改为 8 仍需一块、空 2 个位置；不同长度分布下结论会不同，不能从单条请求选全局最优块大小。"]),
      p("小块通常能更细地贴合长度和共享边界，但块表、索引与分配管理更细碎；大块管理较粗，尾部浪费可能更大。选择块大小还要结合注意力 Kernel 支持、访存组织及实际长度分布。")),
  },
  closing: ["缓存复用节省重复计算；分页解决动态增长和分配组织；前缀共享减少重复状态。三者相互配合，但不是同一项机制。后续调度与抢占，都必须尊重这些块的映射、共享关系和完成依赖。"], references: [PAGED, VLLM],
};

engineSystemTeaching["pd-disagg"] = {
  intro: ["长输入处理与逐步生成，在计算规模和服务目标上有不同特点。PD 分离把 Prefill（处理输入）和 Decode（持续生成）放到不同的执行资源上，使两类资源可以独立配置、扩缩和调度。", "分离的代价是请求状态必须交接。D 端只有拿到后续计算所需的 KV、请求进度和其它必要元数据，才能正确续接。读这门课时持续追踪同一条请求：它在哪里算过，状态在哪里，什么时候真正可被使用。"],
  prerequisites: [pre("Prefill / Decode", "前者处理输入并建立状态，后者在已有历史上持续产生新 Token。二者是同一生成请求的不同工作阶段。", "generation-state"), pre("KV Cache", "历史注意力的 Key/Value 向量。跨设备续接若需要同一历史，就必须传递、恢复或以其它约定获得这些状态。", "kv-cache"), pre("带宽与延迟", "带宽描述单位时间能传多少字节；延迟描述一次操作从发起到完成花多久。小消息可能主要受启动延迟影响，大消息更可能受有效带宽限制。")],
  chapters: {
    ownership: section("交接的是同一个请求的继续执行权",
      p("P 端负责处理输入，D 端负责后续生成；请求身份和已完成位置不能在交接处丢失。路由层还要知道结果应发给哪个客户端。模型状态、计算进度和用户连接是相关但不同的对象，不能用一条‘P→D’箭头全部省略。"),
      table("交接需要保留的含义", ["对象", "用途"], [["历史 KV 与其布局信息", "让 D 端的注意力读取正确历史"], ["请求 ID、序列位置及已完成进度", "知道该继续哪个位置，并把输出返回原请求"], ["生成配置与终止状态", "沿用相应采样、长度和结束约定"], ["完成依赖与资源所有权", "防止未传完就读，或尚在使用就释放"]]),
      p("到底由 P 端还是 D 端完成首个输出的采样，以及具体传哪些元数据，取决于实现协议。先确认系统边界，再讨论传输和延迟，不能把一种实现画成所有系统的固定规则。")),
    bytes: section("从张量形状算清需要交接的字节",
      p("先以普通注意力 KV 为对象：注意力头是分别执行匹配与加权汇总的子计算。每一层、每一个历史位置，都要保存若干组 Key 和 Value 向量，这些组就是 KV 头。把这些轴的长度相乘，再乘每个元素的字节数，就得到未考虑分片和额外元数据时的容量。"),
      formula("普通 KV 的容量估算", "<mrow><mi>M</mi><mo>=</mo><mn>2</mn><mi>L</mi><mi>T</mi><msub><mi>H</mi><mtext>KV</mtext></msub><mi>D</mi><mi>b</mi></mrow>", [["M", "KV 总字节数"], ["2", "分别保存 Key 和 Value"], ["L", "具有此类 KV 的层数"], ["T", "已经缓存的位置数"], ["H_KV", "每层 KV 头数"], ["D", "每头向量元素数"], ["b", "每元素字节数"]], "这里每一项都对应一个真实张量轴。分组查询注意力 GQA 让多个 Query（查询）头共享一个 KV 头，因此查询头数可以大于实际保存的 KV 头数；本式必须使用后者。", ["教学配置 L=32、T=2048、H_KV=8、D=128、b=2。", "容量为 268435456 字节，即 256 MiB。", "实际每设备传输量还取决于张量并行 TP 如何把张量按卡切分、压缩/量化、块布局和协议。", "多头潜在注意力 MLA 把部分历史信息保存为压缩后的潜在向量，状态结构不同，应按其实际保存的向量与附加状态重新计数，不能直接套用本式。"])),
    delivery: section("发送完成、到达可见与允许读取要对齐",
      p("发出传输请求通常只表示工作已提交。D 端不能因此立即把目标地址当作有效 KV。协议需要一个可检查的完成条件，证明必要数据已经到达并满足读取可见性，再允许相应 Decode 计算继续。"),
      p("P 端也不能因为已经开始发送就回收源缓冲；传输引擎可能仍在读取它。完成事件、引用计数和目的端接收状态必须共同约束回收。若部分传输或重试失败，恢复策略还要保证请求进度与实际可用状态一致。"),
      note("这类完成协议与具体通信后端有关。‘异步传输’意味着可与其它工作交叠，不意味着没有同步和所有权约束。")),
    critical: section("分离收益要扣除新增的等待",
      p("用户等待时间包含接纳与排队、P 端处理、状态交接、D 端排队和产生输出等环节。能与其它工作重叠的部分不应重复相加；真正决定完成时刻的是依赖链上无法再重叠的部分，即关键路径。"),
      formula("独立传输阶段的粗略下界", "<mrow><msub><mi>t</mi><mtext>transfer</mtext></msub><mo>≳</mo><mi>α</mi><mo>+</mo><mfrac><mi>M</mi><mi>B</mi></mfrac></mrow>", [["α", "本次传输的启动等固定开销，单位秒"], ["M", "本次实际需搬运的字节数"], ["B", "实际可获得的有效带宽，字节/秒"]], "这个估算帮助判断传输能否被忽略，不是完整端到端时延公式。争用、分块、重排和重叠会改变实际时间。"),
      p("PD 的价值应在给定负载和响应目标下判断：两类工作分离后是否减少相互干扰，是否提高满足延迟约束的有效服务量，同时新增传输和排队是否可接受。单看某个 Prefill Kernel 变快，无法回答这个系统问题。")),
  },
  closing: ["PD 分离重新安排了请求的执行位置，也新增状态交付协议和一段可能进入关键路径的传输。先核对状态正确续接，再用真实负载比较服务收益。"],
  references: [PAGED, ref("DistServe：分离 Prefill 与 Decode", "https://arxiv.org/abs/2401.09670"), ref("vLLM Disaggregated Prefill", "https://docs.vllm.ai/en/v0.11.2/features/disagg_prefill/"), ref("GQA：分组 Query 与 KV 头", "https://arxiv.org/abs/2305.13245"), ref("DeepSeek-V2：MLA 状态表示", "https://arxiv.org/abs/2405.04434")],
};

engineSystemTeaching["serving-slo"] = {
  intro: ["一个 Kernel 更快，不一定让使用者更快得到回答。请求可能先排队，输入处理完成后才出现首个输出，之后还会经历一段逐步生成。服务评价需要把这些不同的等待拆开，再说明系统在多大负载下仍能满足要求。", "本课用事件时刻建立指标。所有时刻必须来自同一条请求、相同测量边界；把时间戳、耗时和吞吐混在一起，会使优化结论失去意义。"],
  prerequisites: [pre("时间戳与时长", "时间戳是一个事件发生的位置；时长由两个事件时间戳相减得到。先固定从客户端还是服务端计时。"), pre("排队与执行", "已到达的请求不一定立刻获得计算资源。等待调度的时间和实际执行时间都可能进入用户的响应时延。", "vllm-scheduler"), pre("SLO", "Service Level Objective，服务目标。例如要求一定比例请求在指定时间内得到首个输出；它应给出指标、阈值和满足比例。")],
  chapters: {
    arrival: section("一条请求的时钟从哪里开始",
      p("记录到达、开始处理、首个输出和最后输出四类事件，可以先把等待位置分清。到达与开始处理之间是排队及相关准备；开始处理与首个输出之间通常包含输入处理、调度和采样等工作，不能只把它称为 GPU Prefill 时间。"),
      p("客户端测得的到达可能从发送请求开始，服务端测量可能从接收或入队开始，网络和解析是否包含其中会不同。比较两个实现前，应使用同一事件定义；否则看似少了几毫秒，可能只是测量窗口变短。"),
      fig("这张简化队列图先看到达、开始服务与完成三种时刻；同样的服务时长可以因排队产生不同响应时间。首 Token 与后续 Token 的交付时刻在下一节单独定义，图上的完成时刻不是 TTFT。")),
    metrics: section("首个输出、后续间隔与总完成时间",
      formula("把三个常用延迟分别定义", "<mtable columnalign=\"left\"><mtr><mtd><mi>TTFT</mi><mo>=</mo><msub><mi>t</mi><mn>1</mn></msub><mo>−</mo><msub><mi>t</mi><mtext>arrival</mtext></msub></mtd></mtr><mtr><mtd><msub><mi>ITL</mi><mi>j</mi></msub><mo>=</mo><msub><mi>t</mi><mi>j</mi></msub><mo>−</mo><msub><mi>t</mi><mrow><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msub></mtd></mtr><mtr><mtd><msub><mi>T</mi><mtext>end-to-end</mtext></msub><mo>=</mo><msub><mi>t</mi><mi>N</mi></msub><mo>−</mo><msub><mi>t</mi><mtext>arrival</mtext></msub></mtd></mtr></mtable>", [["t_arrival", "统一定义的请求到达时刻"], ["tⱼ", "第 j 个输出 Token 在测量边界可见的时刻"], ["N", "实际输出 Token 数；ITL 需要至少两个输出"], ["TTFT / ITL", "首 Token 时延 / 相邻输出 Token 间隔，单位与时间戳一致"]], "三个指标分别回答‘多久开始回答’、‘回答过程中等多久’和‘多久全部完成’。在固定 N 的条件下，最后两个时刻之间才覆盖后续 N−1 个输出间隔。", ["若到达 0 ms，三个输出出现在 20、25、33 ms，则 TTFT=20 ms，ITL 为 5 和 8 ms，总时延 33 ms。", "平均后续间隔是 (33−20)/(3−1)=6.5 ms；不能用 33/3 代替。"]),
      p("若服务将多个 Token 一起传给客户端，网络可见间隔还包含缓冲和传输行为。引擎内部每步执行时长与客户端 ITL 应分别记录，才能定位等待来自哪里。")),
    threshold: section("服务目标评价一组请求的分布",
      p("平均值把快慢样本压成一个数。P95 表示按所采用的分位数定义，大约 95% 的样本不超过该值；它描述分布位置，不是‘最慢 5% 的平均’。报告长尾必须有足够样本和明确的统计方法。"),
      table("同一服务可以同时接受多种约束", ["目标", "需要固定的条件"], [["首个输出及时", "TTFT 阈值、满足比例、输入长度分布"], ["生成过程平稳", "ITL 或相应每请求输出速率定义、输出长度与缓冲策略"], ["有足够服务能力", "测量时长内完成量，以及这些请求是否满足延迟和正确性目标"]]),
      p("Goodput（有效服务吞吐）只计算满足目标的有效请求或输出量。系统若通过让部分请求超时、失败或长时间等待来拉高名义吞吐，未必增加了可用服务能力。")),
    load: section("公平比较必须保持相同的请求压力",
      p("相同并发数不一定产生相同到达压力。闭环压测通常等旧请求结束再发新请求，系统变慢时发送速率也会下降；开放到达流则按给定速率持续送入请求，能够暴露持续排队。两种方式回答不同问题，不能直接混比。"),
      p("固定模型、精度、输入/输出长度、到达轨迹、硬件、缓存策略和错误计数，再逐步增加负载。观察吞吐何时趋于饱和、队列与尾部延迟何时上升，才有依据选择服务工作点。离线满批吞吐不能直接代替在线延迟约束下的容量。")),
  },
  closing: ["服务性能是一组有测量边界的事件与分布。优化时说明改善的是首个输出、持续生成、总完成还是满足目标的服务量，并保持同样的负载条件。"],
  references: [ref("vLLM Production Metrics", "https://docs.vllm.ai/en/v0.11.2/usage/metrics/"), ref("vLLM Bench Serve", "https://docs.vllm.ai/en/v0.11.2/cli/bench/serve/"), TUNING],
};

engineSystemTeaching["host-runtime"] = {
  intro: ["CPU 向 GPU 提交工作后，函数返回与设备工作完成可能发生在不同时刻。这使准备数据、搬运和计算有机会重叠，也使缓冲区的使用权变得关键：下一阶段需要的数据必须完成，上一阶段仍在用的数据不能被覆盖。", "本课把程序中的‘提交’翻译成时间和所有权关系。先保证数据正确，再判断流水是否真正缩短完成时间。"],
  prerequisites: [pre("Host / Device", "这里分别指 CPU 主机侧和 GPU 设备侧。两侧有各自执行进度，部分 API 只负责提交工作。"), pre("Kernel", "一次提交给 GPU 执行的并行函数。它的执行可能在 CPU 提交返回后才开始或完成。", "gpu-execution"), pre("Stream 与 Event", "Stream 是有序工作队列；Event 可用于记录某个队列位置的完成并建立等待关系。跨队列依赖需要显式或由 API 语义保证。", "runtime-graph")],
  chapters: {
    owner: section("提交以后，缓冲区仍可能正在被读取",
      p("CPU 把输入拷贝到设备、设备 Kernel 读取输入、结果再复制回主机，这些动作都有各自的完成边界。只看 CPU 代码已经执行到下一行，无法判断 GPU 是否还在访问某块内存。"),
      table("缓冲区能否复用取决于最后一个使用者", ["缓冲区", "复用前必须确认"], [["主机输入", "异步传输已不再读取这批数据"], ["设备输入/中间结果", "相应 Kernel 或传输已完成访问"], ["主机输出", "设备到主机的复制完成，之后 CPU 才可读出有效结果"]]),
      p("所有权在这里不是‘谁分配了内存’，而是‘当前谁还可能使用这份数据’。把所有权与完成事件对应，才能安全地重复使用内存。")),
    pipeline: section("两套缓冲让相邻批次在不同阶段前进",
      p("单缓冲的循环必须等待这批计算读完，才能把下一批数据放到同一个位置。双缓冲准备两套槽：GPU 使用第 0 套时，另一阶段准备第 1 套；下一轮再交换角色。数据身份仍按批次保持，不能因为槽号相同就混用不同批次。"),
      p("能否重叠还取决于硬件是否支持相应复制/执行并行、主机内存类型、Stream 组织和真实资源争用。增加一套缓冲只是移除了一个复用约束，不会自动制造并行带宽。"),
      fig("图中固定理想双缓冲：B0 搬运在 0–3 ms、计算在 3–8 ms；B1 搬运在 3–6 ms，与 B0 计算重叠，随后在 8–13 ms 计算。这些时长是教学假设；同一批次仍先搬运后计算。", { scenario: 1 })),
    dependency: section("在消费者之前等待，在最后使用之后复用",
      p("同步的作用是建立正确先后关系。若 Kernel 依赖一份复制结果，应让它在复制完成后开始；若不同 Stream 中的工作没有数据依赖，可以保留并行机会。每一步都做全设备同步通常会把本可重叠的阶段串起来。"),
      p("缩小同步范围也有前提：必须覆盖所有实际读写者，不能只删除等待来获得更短的主机计时。一个漏掉依赖的程序可能偶尔正确，负载或执行顺序变化后才暴露错误。")),
    observe: section("用设备时间线验证重叠，而不只看提交代码",
      p("CPU 提交调用重叠，并不能证明 GPU 的搬运与计算重叠。应在时间线上同时标出主机提交、复制操作、Kernel 执行、等待和结果可用事件，观察是否占据同一时间窗口。"),
      p("再比较完整批次的完成时间与稳态间隔。若两个操作都争用同一内存通路，即使时间线上重叠，也可能各自变慢，最后没有端到端收益。正确性、资源争用和完成边界都需要进入结论。")),
  },
  closing: ["异步执行把‘程序已提交’与‘数据已完成’分开。安全流水依赖明确的数据身份、完成事件和复用边界；性能收益来自真实关键路径缩短。"], references: [CUDA, BEST, ref("Nsight Systems User Guide", "https://docs.nvidia.com/nsight-systems/UserGuide/index.html")],
};

engineSystemTeaching["multi-gpu"] = {
  intro: ["模型放到多张卡上后，每张卡拥有的内容决定它缺少什么。切分同一矩阵的输出列，得到的是不同输出坐标；切分参与求和的输入轴，得到的是同一输出的部分贡献；按专家分配，则要把 Token 送到专家所在设备。通信操作必须与这些数学含义一致。"],
  prerequisites: [pre("矩阵乘法的归约轴", "输出的一个元素由输入轴上的多项乘积相加得到；沿这个轴切分，会产生需要相加的部分和。", "gemm-tiling"), pre("Rank", "同一个通信组中参与者的编号。它通常对应一个执行进程及其设备，但不能仅凭编号推断物理连接。"), pre("TP / EP", "张量并行 TP 切分一次模型计算中的张量或权重；专家并行 EP 把不同专家放到不同设备，因而需要按路由结果搬运 Token 激活。", "tensor-parallel")],
  chapters: {
    partition: section("先确定切分轴，再确定需要合并的对象",
      table("同样是两张卡，输出含义可以不同", ["切分方法", "每张卡算出的东西", "后续关系"], [["沿输出特征切权重", "完整输出中的不同坐标", "需要完整向量时按坐标拼接"], ["沿求和的输入特征切权重", "相同输出坐标的部分贡献", "逐坐标相加"], ["按专家放置权重", "被分配给本专家的 Token 计算结果", "按原 Token 身份返回并合并"]]),
      p("通信之前先把每个值的坐标和身份标出来。同样长度的两个向量可能代表不同坐标，也可能代表同一坐标的两份贡献；只看数组尺寸无法选择正确的通信。")),
    reduce: section("AllReduce 让每个参与者得到归约结果",
      p("Reduce（归约）把多个参与者对应坐标的值用规定操作合并，例如求和。AllReduce 再要求每个参与者都得到合并后的结果。‘All’描述结果在哪里，‘Reduce’描述数学上怎样合并。"),
      formula("逐坐标求和归约", "<mrow><msub><mi>y</mi><mi>j</mi></msub><mo>=</mo><munder><mo>∑</mo><mi>r</mi></munder><msub><mi>x</mi><mrow><mi>r</mi><mo>,</mo><mi>j</mi></mrow></msub></mrow>", [["r", "通信组里的参与者编号"], ["j", "结果坐标"], ["xᵣ,ⱼ", "参与者 r 对坐标 j 提供的值"], ["yⱼ", "归约后的坐标值"]], "求和只发生在相同坐标之间。若两张卡分别提供 [1,2] 和 [6,8]，求和结果是 [7,10]，AllReduce 后双方都得到它。"),
      p("参与者必须对数据类型、数量、操作和通信次序保持一致。数学关系正确只是必要条件，实际调用还要满足通信库的协作规则。")),
    gather: section("拼接、归约与分发对应不同的结果布局",
      p("AllGather 收集各参与者已有的不同片段，让所有参与者得到完整拼接结果。ReduceScatter 先进行归约，再让各参与者只保留结果的一部分。两者不是缩写不同的同一操作。"),
      table("看输入含义与结果归属", ["操作", "做什么", "每个参与者最终拿到什么"], [["AllGather", "按约定次序收集片段", "全部片段"], ["AllReduce", "合并同坐标贡献", "完整归约结果"], ["ReduceScatter", "合并同坐标贡献后切片", "归约结果的一个片段"]]),
      p("当下一层本来就按片段工作时，未必需要让每张卡都持有完整结果。通信与后续张量布局一起设计，可以避免不必要的全量复制。")),
    cost: section("传了多少与用了多久，需要分别解释",
      p("数据量帮助判断通信压力，但耗时还受消息大小、启动成本、拓扑、链路争用和计算重叠影响。连接两个 GPU 的逻辑边不代表它们之间一定有独占高速通路。"),
      p("报告通信成本时说明统计边界：单个 Rank 的发送量还是收发总和、一个阶段还是整层、物理链路字节还是有效载荷。随后以真实 Trace 判断哪些通信阻塞了消费者，哪些已经被其它工作覆盖。只有关键路径上的变化才能直接解释端到端改善。")),
  },
  closing: ["多卡推理的主线是：权重和数据怎样切分，局部结果代表什么，怎样用正确的通信恢复后续所需布局。先建立这条数学与数据关系，再分析具体拓扑和速度。"], references: [NCCL, ref("Megatron-LM：模型并行分解", "https://arxiv.org/abs/1909.08053"), VLLM],
};

engineSystemTeaching["warp-issue"] = {
  intro: ["一个 Warp 已经驻留在 GPU 上，仍可能没有可发射的下一条指令：它也许在等一次加载的结果、等其它线程到达同步点，或者等所需执行资源。理解这些等待，才能把性能报告里的 Active、Eligible 和 Issued 读成执行过程。", "本课从一条‘先加载、后使用’的依赖出发。示意周期只说明先后关系，不是某代 GPU 的固定延迟。"],
  prerequisites: [pre("Warp / Lane", "在本课 CUDA 模型中，Warp 是 32 个线程组成的执行组，Lane 是组内线程位置。一个 Warp 的下一步是否可发射，与它的指令和依赖有关。", "gpu-execution"), pre("指令依赖", "某条指令需要前一条指令产生的数据时，必须等该数据满足使用条件。源代码相邻与数据依赖是两回事。"), pre("Scoreboard", "用于跟踪尚未满足的依赖的一类硬件记账机制。它帮助判断某个结果是否可被后续指令使用，而不是模型请求的调度队列。")],
  chapters: {
    dependency: section("数据尚未回来，依赖它的计算就不能前进",
      p("例如先加载一个值，再把它用于加法。发出加载请求只是访问开始，加载结果尚未可用时，加法就不能读取正确输入。Scoreboard 跟踪这种未完成依赖，阻止消费者过早发射。"),
      p("等待期间，硬件有可能选择其它就绪 Warp 的指令。能否利用这段时间，取决于是否存在独立工作、目标执行资源是否可用，以及具体调度规则。把等待标出来，才能看清‘计算单元没忙’究竟缺少什么。"),
      table("只看 W0 的一条加载依赖：假设结果在人工周期 4 可用", ["人工周期", "W0 的状态", "发射槽"], [["0", "发出加载，结果尚未返回", "加载 LD"], ["1–3", "后续加法等待加载结果", "没有其它独立 Warp，槽空闲"], ["4", "加载结果可用，加法满足数据依赖", "加法 ADD"]]),
      p("这个基准只用来显示等待的原因。若另一个 Warp 此时有独立的就绪指令，它可能填补中间的空槽，但不会缩短 W0 这次加载本身的延迟。真实 GPU 的加载延迟不固定为这里的 4 周期。")),
    states: section("驻留、就绪、被选中是三个不同集合",
      table("三个状态回答不同问题", ["术语", "含义", "仍可能缺少什么"], [["Active / Resident", "当前已经占有资源并驻留的 Warp", "数据、同步条件或执行资源"], ["Eligible", "这一时刻可发射下一条指令的 Warp", "仍需调度器选中"], ["Issued", "这一时刻实际被选中发射的 Warp", "后续指令仍可能再次等待"]]),
      p("因此，驻留数高不能推出每周期都有很多就绪工作；就绪数大于发射数，也不自动说明异常，因为发射能力有限。指标必须结合采样范围、调度器和目标指令资源解读。")),
    hide: section("延迟隐藏靠独立工作填补等待窗口",
      p("增加独立 Warp 或同一线程内的独立指令，都可能在某条依赖等待时提供其它可执行工作。它们不会让原来的内存访问凭空缩短，而是减少执行资源因等待而空闲的时间。"),
      p("如果所有 Warp 同时等待相同类型的长延迟访问，或都争用已经饱和的通路，再增加相似工作未必有效。要把‘等待变短’与‘等待被其它工作覆盖’区分开，才能选择预取、并行度或数据重用等不同方向。")),
    resources: section("更多并行工作也会消耗更多资源",
      p("每个驻留线程需要寄存器，线程块（CTA，由一组可协作的线程组成）还可能需要 Shared Memory，也就是块内线程共享的片上存储。较大的工作块或更深的软件流水可以提供重用和独立工作，却也可能增加这些资源需求，降低可同时驻留的 CTA 数。"),
      p("判断优化时，把资源占用、就绪工作、实际发射和总时间连起来。Occupancy 是驻留 Warp 数相对硬件 Warp 上限的比例。减少一次加载可能比盲目提高这个比例更有效；反过来，资源使用过大导致几乎没有可替换工作，也可能使等待完全暴露。具体原因需要代码依赖和测量共同支持。")),
  },
  closing: ["驻留说明工作已经进入设备，就绪说明依赖允许前进，发射说明这一时刻实际获得执行机会。优化要解释三者之间缺失的条件，而不只追求一个比例。"], references: [CUDA, NSIGHT],
};

engineSystemTeaching["memory-route"] = {
  intro: ["GPU 程序看到的是地址和数据，硬件则要把许多线程的请求组织成实际存储访问。相同数量的元素，若分散到很多地址段，可能需要搬来更多无关数据；同一数据若被反复使用，又可以通过缓存或显式分块减少远端访问。", "寄存器、Shared、Cache 和 HBM 分别承担不同职责。理解它们要追踪数据由谁使用、保留在哪里、怎样被访问，不能只背一张速度排行榜。"],
  prerequisites: [pre("HBM", "高带宽显存，通常保存模型权重、激活和 KV 等大规模数据。带宽高不意味着单次访问没有延迟。"), pre("寄存器与 Shared", "寄存器保存线程使用的局部值；Shared 是线程块（CTA）可协作访问的一块片上存储，需要程序组织装入、使用和同步。", "gpu-execution"), pre("Cache", "硬件管理的缓存，保留部分访问过的数据以服务后续访问。命中与否取决于访问和替换行为，不能完全按程序意愿锁住所有数据。")],
  chapters: {
    addresses: section("先写出每个 Lane 实际请求的字节地址",
      p("一个 Warp 中各 Lane 的加载并不是 32 次完全孤立的操作。硬件会按指令与地址组织访问事务。相邻线程访问相邻元素，往往能让同一段返回数据服务多个线程；跨步或错位访问可能覆盖更多地址段。"),
      p("例如每个线程读取一个 4 字节元素，Lane i 的地址为基址加 4i 时，请求集中在一段连续范围；若变成基址加 128i，请求就很分散。比较时还要检查基址对齐、访问宽度和实际指令，不能只看下标有没有连续。"),
      fig("由 Lane 的字节地址看它们覆盖了哪些存储段。线表示请求归属，不能把示意段数直接当真实 HBM 事务数。")),
    coverage: section("有效数据与实际覆盖量为什么会不同",
      formula("在已指定事务模型下计算有效载荷比例", "<mrow><mi>η</mi><mo>=</mo><mfrac><msub><mi>B</mi><mtext>useful</mtext></msub><msub><mi>B</mi><mtext>covered</mtext></msub></mfrac></mrow>", [["B_useful", "被消费者真正需要的有效字节数；需声明是否按唯一地址去重"], ["B_covered", "指定模型中访问段覆盖的总字节数"], ["η", "该模型下的有效载荷比例"]], "这个比例解释为何相同有效输入可能触发不同数据覆盖量。它不是缓存命中率，也不是 HBM 带宽利用率。"),
      p("真实访问还经过缓存、合并、写回等环节，因此程序请求的字节、L1/L2 流量和显存流量不一定相等。先固定所观察层级，再用计数器核对；否则分母一换，就会把不同现象都叫‘访存效率低’。")),
    shared: section("显式重用与硬件缓存解决问题的方式不同",
      table("数据怎样留在近处", ["存储方式", "谁组织保留与使用", "主要需要考虑"], [["寄存器", "编译器分配线程局部值", "活跃值数量、访问方式和溢出"], ["Shared Memory", "程序显式装入并由 CTA 协作使用", "装入成本、同步、Bank 映射与驻留资源"], ["硬件 Cache", "硬件按访问与替换规则管理", "局部性、工作集和争用"], ["HBM", "容纳大规模持久与中间数据", "实际流量、并发请求和带宽"]]),
      p("例如矩阵 Tile 被多次使用时，装入 Shared 后复用可以减少重复远端读取，但也增加协作与同步。若数据只使用一次，复制到 Shared 未必值得。缓存能够命中时，显式搬运的额外收益也需要重新衡量。")),
    measure: section("由访问证据推导优化方向",
      p("先从代码估算每个输出需要读写哪些数据、哪些读取可以复用，再观察实际层级流量、访问合并和依赖等待。低 L2 命中率可能符合一次性流式访问的设计，不能单独证明程序差；高命中率也不能保证关键路径已足够短。"),
      p("有效实验应改变一个明确机制，例如让索引更连续、减少重复加载或调整 Tile 复用，然后同时验证结果、资源使用和时间。把地址模式、流量和耗时接起来，比凭一个命中百分比决定优化更可靠。")),
  },
  closing: ["访存分析从实际地址开始，经访问组织和数据复用走到真实流量与依赖。每一层都有自己的计量边界，不能用一个‘带宽’数字代替整条路径。"], references: [CUDA, BEST, NSIGHT],
};

engineSystemTeaching["tensorcore-b200"] = {
  intro: ["Tensor Core 是执行特定矩阵乘加的专用计算单元。它能高效完成乘加，但不能替程序解决输入布局、数据搬运、结果保存和依赖同步。一个高效 Kernel 必须让这些环节配合起来。", "本课以 Blackwell 公开 tcgen05 指令体系为参照，理解矩阵块、异步搬运、Tensor Memory 与完成协议。讲解的是公开机制，不用示意节拍估算 B200 的真实周期。"],
  prerequisites: [pre("Tile 与累加", "Tile 是矩阵中的一块。矩阵乘法沿 K 轴分块时，各块贡献累加到同一输出 Tile；中间累加结果必须跨块保存。", "gemm-tiling"), pre("Shared / TMEM", "Shared 是线程块（CTA）的协作存储；Tensor Memory（TMEM）是 tcgen05 体系提供的专门存储，用于相应矩阵操作的数据和累加结果，不能把它当作普通寄存器数组。"), pre("异步完成", "提交一条操作与该操作完成可以分离。消费者要等正确的完成条件，生产者要等数据不再被使用后才能复用缓冲。", "host-runtime")],
  chapters: {
    tile: section("矩阵乘加之前，操作数必须以合法布局就位",
      formula("一次矩阵块乘加的数学任务", "<mrow><mi>D</mi><mo>←</mo><mi>A</mi><mi>B</mi><mo>+</mo><mi>D</mi></mrow>", [["A", "M×K 的输入块"], ["B", "K×N 的输入块"], ["D", "M×N 的累加块"], ["M / N / K", "当前指令或 Kernel 组织的矩阵维度"]], "数学形状匹配只是第一层条件。具体指令还规定数据类型、布局、对齐和支持的形状，不能把任意矩阵直接当作合法操作数。"),
      p("在所引用 tcgen05 体系中，B 操作数来自 Shared，A 可按指令形式来自 Shared 或 TMEM，D 累加结果位于 TMEM。Kernel 必须准备正确描述和布局；装入了相同数值但布局解释不一致，仍然会算错。"),
      p("因此一个 Tile 的流程至少涉及操作数就位、矩阵指令消费、累加结果可用和后续读出。Tensor Core 峰值只描述其中一个环节的能力。")),
    double: section("用不同缓冲交叠装入与矩阵计算",
      p("若每个 K 块都先等待加载完成，再做矩阵乘加，数据准备和计算就串行发生。双缓冲让当前块被消费时，下一块装入另一套槽；当两边都满足依赖，交换槽的角色。"),
      p("这需要两个方向的约束：计算不能读取尚未装好的下一块，装入也不能覆盖仍被矩阵操作读取的当前块。把缓冲槽与块编号同时标出，就能区分‘这块可读’和‘这个槽可重用’。"),
      fig("图中相邻块交叠的是不同阶段；同一块的装入完成依赖依然保留。示意时长不代表实际设备比例。")),
    barrier: section("完成信号必须对应实际异步操作",
      p("搬运完成和矩阵运算完成是不同事件。一个用于确认数据到达的屏障，不能自动证明矩阵累加已经结束；相应计算完成前也不能提前读取 TMEM 结果或复用相关资源。"),
      p("PTX tcgen05 提供把先前异步矩阵操作的完成关联到 mbarrier（内存屏障对象）的机制。使用者还必须遵循文档规定的线程协作、阶段状态和内存顺序。普通线程屏障只能提供其定义的同步语义，不能替代所有专用异步协议。"),
      note("这里解释每个完成信号负责什么。完整可运行指令序列需要固定目标、指令形式和参与线程，不能直接把这段文字翻成几条任意拼接的 PTX。")),
    limits: section("更多流水级数只有在覆盖瓶颈时才有用",
      p("增加缓冲级数可以提前准备更多块，但同时占用更多 Shared、描述信息和同步状态，也可能影响可驻留的 CTA 数。如果瓶颈已经是矩阵吞吐或同一搬运通路，继续加深流水未必缩短时间。"),
      p("评估时先指出当前空泡来自数据尚未到达、消费者依赖、发射条件还是输出处理，再改相应环节。将编译资源报告、真实指令路径和时间线对应起来，才有理由判断哪个流水配置更合适。")),
  },
  closing: ["矩阵单元的高效使用依赖一整套数据与完成协议：把正确 Tile 放到正确位置，在正确时刻消费，再安全读出和复用。数学吞吐、数据供给与资源占用必须一起分析。"], references: [ref("PTX ISA 8.8：tcgen05、TMEM 与完成机制", "https://docs.nvidia.com/cuda/archive/12.9.1/parallel-thread-execution/index.html#tensorcore-5th-generation-instructions"), CUDA, NSIGHT],
};

engineSystemTeaching["spec-decode"] = {
  intro: ["普通自回归生成每确定一个 Token，才继续下一步。推测解码让一个便宜的提议过程先猜出多个候选，再由目标模型一起检查，希望一次较昂贵的验证能确认多个位置。收益来自减少昂贵模型的串行轮数。", "候选不是最终答案。为了保持目标模型所定义的生成行为，必须说明怎样接受、哪里停止接受、拒绝后怎样纠正。以下概率公式对应经典随机采样的推测验证；贪心匹配和不同 MTP 实现需要按各自规则分析。"],
  prerequisites: [pre("概率分布与采样", "模型给每个候选 Token 一个概率，采样按这些概率随机选一个编号。分布相同不意味着每次选到同样 Token。", "sampling-distribution"), pre("自回归条件", "当前 Token 的分布依赖已经确认的前缀；中途一个候选被拒绝后，以它为前提产生的后续候选不能直接保留。", "generation-state"), pre("Draft / Target", "Draft 是候选提议过程，Target 是决定期望输出分布的目标模型。候选也可能由额外预测头提供，不能把所有方案都当作独立小模型。")],
  chapters: {
    draft: section("先提出一段候选，再验证其连续前缀",
      p("提议器基于已确认前缀生成若干候选 Token。目标模型可以在这些已知候选构成的序列上计算对应位置的条件分数，从而一次检查多个位置。这样的批量验证没有取消自回归依赖：每个位置的条件前缀仍然明确。"),
      p("验证通常从第一个候选依次判断，只接受连续通过的前缀。一旦中途失败，后面的候选依赖了错误的前缀，需要舍弃或重新处理。候选长度大只说明提出得多，不说明最终能前进同样多的位置。"),
      p("经典算法还利用验证最后一个候选时得到的‘下一个位置’分布：若这段候选全部接受，可以再按目标分布采一个额外 Token。于是一次验证可能接受 k 个候选并采出第 k+1 个输出；这个额外 Token 的编号已确定，但其后续模型计算仍待进行。若途中拒绝，则从下一节的纠正分布采一个 Token 后结束本段；停止条件与具体实现可能进一步截断输出。")),
    accept: section("接受概率纠正提议器与目标分布的差别",
      formula("经典推测采样的单个候选接受概率", "<mrow><mi>a</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mi>min</mi><mo>(</mo><mn>1</mn><mo>,</mo><mfrac><mrow><mi>p</mi><mo>(</mo><mi>x</mi><mo>)</mo></mrow><mrow><mi>q</mi><mo>(</mo><mi>x</mi><mo>)</mo></mrow></mfrac><mo>)</mo></mrow>", [["x", "由提议分布实际采到的候选 Token，因此 q(x)>0"], ["q(x)", "在同一前缀下，提议器给候选的概率"], ["p(x)", "目标模型给同一候选的概率"], ["a(x)", "接受候选的概率"]], "提议器若给某候选的概率份额过多，就只保留其中一部分；若没有超出目标份额，则可以全接受。这里把某个事件分到的概率份额称为概率质量。被提议并接受的联合概率质量是 min(p(x),q(x))。", ["例如 q(x)=0.6、p(x)=0.3，接受概率为 0.5；提议并接受 x 的概率为 0.6×0.5=0.3。", "若 q(x)=0.2、p(x)=0.3，则接受概率为 1，但这只贡献 0.2，剩余目标质量由拒绝后的纠正补足。"]),
      p("这个规则要求 p 与 q 使用相同前缀下的实际采样分布；若采样还包含温度或候选筛选，它们也属于分布定义。这里匹配的是整个随机输出规律，不要求目标单独采样时恰好产生同一串随机 Token。")),
    reject: section("拒绝后从剩余概率质量中重新采样",
      formula("拒绝时使用归一化后的正残差分布", "<mrow><mi>r</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mfrac><mrow><mi>max</mi><mo>(</mo><mi>p</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>−</mo><mi>q</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>,</mo><mn>0</mn><mo>)</mo></mrow><mrow><munder><mo>∑</mo><mi>y</mi></munder><mi>max</mi><mo>(</mo><mi>p</mi><mo>(</mo><mi>y</mi><mo>)</mo><mo>−</mo><mi>q</mi><mo>(</mo><mi>y</mi><mo>)</mo><mo>,</mo><mn>0</mn><mo>)</mo></mrow></mfrac></mrow>", [["r(x)", "发生拒绝后的纠正分布"], ["p、q", "同一前缀下目标与提议的完整概率分布"], ["y", "遍历词表的求和索引"]], "已经通过接受阶段保留的质量是 min(p,q)，剩余需要补足的是 p−min(p,q)=max(p−q,0)。分母把这些剩余质量归一化。"),
      p("教学例 p=[0.3,0.7]、q=[0.6,0.4]：接受通路保留 [0.3,0.4]，尚缺 [0,0.3]，因此拒绝后只补第二项。两个通路合起来恢复 p。不能简单地在拒绝后任意重采样，再宣称分布保持不变。"),
      note("若 p=q，则没有需要纠正的剩余质量，拒绝事件概率为零；公式用于实际会发生拒绝的条件。有限精度与具体实现仍需单独验证。")),
    cost: section("一次验证推进多少，与多付出的成本一起算",
      p("一次验证能确认更多位置时，昂贵目标模型的串行调用数可能下降。但提议本身要花时间，验证更长序列要做更多工作，也可能需要额外 KV、数据组织和回退处理。接受率低或提议成本高时，收益会被抵消。"),
      p("应比较相同生成语义下的端到端时间、每次验证平均前进的位置数和相应开销，而不是只报候选长度或接受百分比。MTP（多 Token 预测）提供候选能力的方式可以不同，能否保持目标行为仍取决于验证协议。")),
  },
  closing: ["推测解码用便宜的候选与严格的验证，换取更少的昂贵串行轮次。概率纠正保证的是指定算法下的目标分布；加速则另外依赖接受情况和完整执行成本。"], references: [ref("Fast Inference from Transformers via Speculative Decoding", "https://arxiv.org/abs/2211.17192"), ref("vLLM Speculative Decoding", "https://docs.vllm.ai/en/v0.11.2/features/spec_decode/")],
};

engineSystemTeaching["quant-pipeline"] = {
  intro: ["量化把原来的数值映射到较少的可表示值，希望减少权重、激活或缓存的存储与搬运，并利用相应硬件计算。位数变少只是开始：数值误差、Scale、打包布局和 Kernel 支持共同决定它能否正确且有效地运行。"],
  prerequisites: [pre("dtype", "数据类型规定数值的编码方式、可表示范围和精度，例如 BF16、整数或某种 FP8。位数相同也可能有不同数值含义。"), pre("Scale", "把一组真实数值与低精度编码联系起来的缩放因子；这里约定重建近似值为 Scale 乘编码值。"), pre("舍入与截断", "舍入把数值移到邻近可表示点；截断把超出范围的数值压到边界。两种误差来源不同。")],
  chapters: {
    grid: section("缩放因子定义这组数值使用的刻度",
      formula("对称整数均匀量化的教学定义", "<mtable columnalign=\"left\"><mtr><mtd><mi>q</mi><mo>=</mo><mi>clip</mi><mo>(</mo><mi>round</mi><mo>(</mo><mi>x</mi><mo>/</mo><mi>s</mi><mo>)</mo><mo>,</mo><msub><mi>q</mi><mtext>min</mtext></msub><mo>,</mo><msub><mi>q</mi><mtext>max</mtext></msub><mo>)</mo></mtd></mtr><mtr><mtd><mover><mi>x</mi><mo>^</mo></mover><mo>=</mo><mi>s</mi><mi>q</mi></mtd></mtr></mtable>", [["x", "原始数值"], ["s>0", "这一组的缩放因子"], ["q", "低精度整数编码"], ["q_min / q_max", "本例允许的编码边界"], ["x̂", "反量化得到的近似值"]], "先除以刻度得到编码坐标，再舍入并限制范围；重建时乘回同一刻度。这里没有 Zero Point（表示真实零值的编码偏移），不能直接代表所有含偏移的仿射量化或浮点量化格式。", ["x=0.7、s=0.25，若范围足够，则 x/s=2.8，舍入得到 q=3。", "重建值为 0.75，误差为 0.05。Scale 定义的是编码如何解释，不是额外学到的每个元素值。"]),
      p("q=3 单独不能告诉使用者近似值是多少：Scale=0.25 时代表 0.75，Scale=0.5 时代表 1.5。因此低精度编码和相应的缩放信息必须配套保存与读取。")),
    range: section("保护大值与分辨小差异之间的取舍",
      p("编码数量固定时，Scale 较大意味着覆盖更宽的实际范围，但相邻重建值更远；Scale 较小意味着局部间隔更细，但大值更容易超过范围。异常大值可能迫使整组使用较粗刻度，使同组小值损失分辨率。"),
      p("按通道或按块分组，可以让不同区域使用更合适的 Scale，同时增加 Scale 元数据和相应处理成本。评价时既要看逐元素误差，也要看模型任务质量；较小的平均数值误差并不自动保证每项任务表现更好。")),
    format: section("整数与浮点的可表示点分布不同",
      table("先明确编码，再讨论位数", ["类型", "核心结构", "理解重点"], [["低比特整数", "整数编码配合 Scale，可含 Zero Point", "固定 Scale 下的均匀网格与饱和边界"], ["FP8", "符号、指数与有效数位；存在不同格式", "范围与精度随格式和数值区间变化"], ["FP4 及块缩放方案", "更少编码位配合明确的缩放与分组规则", "具体格式、Scale 类型和块大小缺一不可"]]),
      p("E4M3 和 E5M2 是两种 FP8 编码，指数位与尾数位分配不同。‘FP4’也不足以唯一指定数值规则；对接 Kernel 时必须知道具体格式及打包方案。不能把前一节的均匀整数网格直接画成所有浮点格式。")),
    backend: section("存得下以后，还要有正确的执行路径",
      p("权重文件的量化格式、GPU 支持的数据类型、Kernel 要求的布局和模型算子必须匹配。运行时可能需要解包、读取 Scale、转换或使用专用低精度指令；这些步骤决定真实计算路径。"),
      p("低精度权重减少的字节不等于端到端时间同比减少。若反量化成本、布局转换或其它未量化算子占主导，收益可能有限；若真实瓶颈是权重搬运，节省流量则可能很重要。应同时核对任务质量、正确性与实际派发到的 Kernel。")),
  },
  closing: ["量化需要连接数值映射、存储格式与执行实现。位数和 Scale 解释‘怎样近似’，Kernel 与工作负载解释‘能否更快’，模型评价解释‘近似是否可接受’。"], references: [ref("FP8 Formats for Deep Learning", "https://arxiv.org/abs/2209.05433"), ref("TensorRT 量化说明", "https://docs.nvidia.com/deeplearning/tensorrt/latest/inference-library/work-with-quantized-types.html"), ref("PTX ISA 8.8：块缩放矩阵指令", "https://docs.nvidia.com/cuda/archive/12.9.1/parallel-thread-execution/index.html")],
};

engineSystemTeaching["frameworks"] = {
  intro: ["vLLM、SGLang、TensorRT-LLM 等推理系统都能执行模型，但它们组织请求、缓存、编译和 Kernel 的路径不一定相同。‘哪个更快’只有放在固定模型、输入和服务目标下才有可比较的含义。", "这门课建立比较方法，不给脱离版本和负载的排行榜。学完后，应能把一个性能结论拆成可复现条件、实际执行路径和服务指标。"],
  prerequisites: [pre("Backend", "负责某一类计算的具体实现，例如某种注意力 Kernel 或矩阵乘库；相同前端接口可能选择不同后端。", "backend-dispatch"), pre("吞吐与延迟", "吞吐是单位时间完成的工作量，延迟是单个请求或步骤等待多久。提高批量可能改善前者，同时影响后者。", "serving-slo"), pre("可复现条件", "他人需要用相同模型版本、精度、输入、软件和硬件配置重建比较，才能核对结论。", "deployment-compatibility")],
  chapters: {
    contract: section("比较前先固定要完成的同一项任务",
      p("相同模型名字不代表相同计算：权重版本、量化格式、采样设置、上下文长度和输出长度都可能改变工作量与结果。先确认正确性和任务质量要求一致，再固定硬件和软件版本。"),
      p("在线聊天、长文处理和离线批量生成的目标不同。比较报告应写清目标是首个输出、持续输出间隔、总时间，还是满足服务约束的吞吐。条件不同的数字可以描述各自场景，但不能直接排列成普遍优劣。")),
    backend: section("从相同 API 追到真实执行路径",
      p("API 只是调用边界。请求进入系统后，可能经过不同的调度、前缀缓存、图捕获、Kernel 派发和分布式通信。某个特性在配置里打开，也不证明当前输入真的走到了该路径。"),
      p("应记录支持条件、选择日志或可观察的实际 Kernel，再解释性能差异。若一种系统回退到通用实现，另一种走专用路径，结论首先说明这个配置下的执行差异，而不能立即外推到所有模型。")),
    tail: section("吞吐提升需要与等待分布一起读",
      p("更大的批次或更激进的资源复用，可能提高单位时间处理量，也可能让部分请求等得更久。平均时延还会隐藏少数长等待；服务可用性需要观察目标分位数、失败和超时。"),
      table("把比较结论说完整", ["单独报告", "还应补充"], [["每秒输出 Token 增加", "对应输入/输出分布、延迟约束和错误量"], ["平均延迟降低", "首个输出、生成间隔与尾部分布"], ["显存使用减少", "是否改变精度、并发、缓存策略和任务质量"]])),
    repeat: section("保留别人可以复查的证据链",
      p("保存模型 revision、完整配置、输入轨迹、测量脚本和原始样本。说明是否包含冷启动、编译、缓存预热、网络和结果传输，保留失败样本及重复运行差异。"),
      p("得到差异后，再做可归因的对照，例如固定后端只改变批次预算，或固定负载只改变缓存命中条件。一次综合对比能说明‘这个组合更快’，逐项对照才帮助解释‘为什么更快’。")),
  },
  closing: ["引擎比较应产生有条件的工程判断：哪个版本、哪种执行路径，在什么工作负载与质量约束下改善了哪个指标。没有固定条件的排名不构成可迁移的知识。"], references: [VLLM, ref("SGLang 官方文档", "https://docs.sglang.ai/"), ref("TensorRT-LLM 官方文档", "https://nvidia.github.io/TensorRT-LLM/"), NSIGHT],
};

engineSystemTeaching["request-lifecycle"] = {
  intro: ["一个请求从收到输入到返回最后一个 Token，要经过队列、批次重组、设备执行和结果交付。过程中它在数组里的位置可以改变，身份却必须保持。结束或取消请求，还涉及在途工作和缓存回收，不能只修改一个状态字符串。"],
  prerequisites: [pre("请求 ID", "在系统中标识同一条请求的稳定编号，用于把调度、状态、输出和客户端对应起来。"), pre("Batch 行号", "一次执行中数据所在的临时行位置，下一轮重组后可能改变。它不能替代请求身份。", "batch-executor"), pre("在途工作", "已经提交但还没完成的计算或传输；即使上层改变请求状态，它仍可能读取相关内存。", "host-runtime")],
  chapters: {
    identity: section("身份不随排队位置和批次行号改变",
      p("请求可能先在等待队列中排第 3，进入某一轮批次后成为第 0 行，下一轮又被排到第 2 行。这些位置服务于当时的数据组织，不能决定结果属于谁。系统需要把临时位置映射回稳定请求 ID。"),
      p("同样，序列里的 Token 位置也不是 Batch 行号：前者描述请求内部的历史，后者描述本轮张量组织。明确这三种坐标后，才能安全重排、合并不同长度输入并返回输出。"),
      table("需要同时保留的三种身份", ["标识", "回答的问题"], [["request ID", "这条数据属于哪条请求"], ["sequence position", "它在这条请求的哪个序列位置"], ["batch row / offset", "它在当前执行输入的哪里"]])),
    cancel: section("取消改变后续安排，不能抹去已提交访问",
      p("用户取消后，系统可以停止再安排新的生成工作，并丢弃之后返回的无用输出。但已经提交给 GPU 的 Kernel 或传输可能仍在读取这条请求的缓冲和 KV。逻辑取消与物理访问结束并不同步。"),
      p("因此回收应等待实际使用结束。若取消后立刻把同一块内存交给新请求，新请求的写入可能覆盖旧 Kernel 还在读取的数据。错误可能表现为偶发结果污染，而不是一次明确的越界访问。")),
    finish: section("返回完成、设备完成与资源可回收分别记账",
      table("三个完成边界", ["事件", "可以作出的判断", "仍需核查"], [["最后结果交给客户端", "用户输出流程结束", "是否仍有设备或传输工作使用缓冲"], ["相关设备工作完成", "相应操作不再访问这些数据", "是否还有其它请求共享 KV"], ["最后依赖和引用解除", "资源可以按缓存策略复用或淘汰", "是否需要保留可复用前缀"]]),
      p("正常完成、取消和失败都应遵守同样的资源原则。错误处理还要防止重复回收或遗留引用。把用户可见结果和资源生命周期分开，才能同时解释服务指标、内存占用与正确性。")),
  },
  closing: ["稳定请求身份贯穿排队与批次重排；完成依赖贯穿结果返回与资源回收。状态机必须同时保护这两条关系。"], references: [VLLM, CUDA, PAGED],
};

engineSystemTeaching["model-loading"] = {
  intro: ["模型下载到磁盘后，还要把权重按计算需要装入内存与显存，建立各设备的职责，并为运行时留下空间。能读取权重文件，不等于能承受目标并发和上下文长度。", "本课把磁盘文件组织、并行切分、数值格式和运行时预算分开，避免用‘模型有多少 GB’代替完整部署判断。"],
  prerequisites: [pre("权重与激活", "权重是已训练模型的参数；激活是一次输入计算产生的中间值。权重通常跨请求复用，激活随当前计算产生。", "transformer-layer"), pre("Checkpoint", "保存模型参数及相关配置的文件集合。为了下载和读取方便可拆成多个文件，文件边界不必对应设备切分。"), pre("KV 与工作空间", "KV 保留请求历史；工作空间保存 Kernel、通信或执行器临时使用的数据。它们都可能与权重同时占显存。", "kv-cache")],
  chapters: {
    files: section("文件分片与设备分工是两种切分",
      p("一个权重张量可能被保存在某个 checkpoint 文件中，装载时再按并行策略切给不同设备。文件拆分解决存储与加载组织；张量并行 TP 切分同一次计算的张量，流水并行 PP 把连续层段分给不同设备。后两者解决计算与设备职责，文件边界不必与它们一一对应。"),
      p("装载器需要理解参数名、形状、数值类型和模型结构，再把对应部分放到目标设备。只把若干文件平均分给 GPU，无法保证每张卡拿到合法的计算分片，也可能重复或漏掉参数。")),
    bytes: section("可运行显存必须容纳同时存在的对象",
      formula("按同时驻留对象建立显存预算", "<mrow><msub><mi>M</mi><mtext>need</mtext></msub><mo>=</mo><msub><mi>M</mi><mtext>weights</mtext></msub><mo>+</mo><msub><mi>M</mi><mtext>KV</mtext></msub><mo>+</mo><msub><mi>M</mi><mtext>workspace</mtext></msub><mo>+</mo><msub><mi>M</mi><mtext>other</mtext></msub></mrow>", [["M_weights", "本设备驻留权重，包括相应量化元数据"], ["M_KV", "目标并发和长度下的缓存容量"], ["M_workspace", "当前运行所需中间与临时工作空间"], ["M_other", "执行环境、通信、图或内存管理等其它开销"]], "这是预算分类，不是声称所有峰值在同一瞬间达到最大。需要结合生命周期判断哪些对象会同时存在，并为已观测波动保留余量。"),
      p("权重刚好装入并不能保证生成能继续。并发请求或上下文增长会增加 KV，某些 Kernel 配置会需要额外工作空间，首次图捕获或临时转换也可能产生不同峰值。应以目标负载验证实际峰值与分配行为。")),
    dtype: section("文件格式、驻留格式与计算格式可以不同",
      p("从文件读取的数据可能先在主机上转换，也可能复制到设备后再重排、量化或转换。临时同时保存旧格式和新格式，会增加加载期峰值；一次性转换成本也应与稳态推理成本分开。"),
      p("低精度驻留权重可能由 Kernel 在使用时反量化，或由专用指令直接参与相应计算。必须记录实际格式与路径，不能从文件扩展名或模型名称推断 GPU 上究竟读了什么。")),
  },
  closing: ["装载是把文件中的参数组织成设备上的可执行模型。部署容量则由权重、请求状态、临时空间和同时驻留关系共同决定。"], references: [VLLM, ref("Safetensors 格式与分片装载", "https://huggingface.co/docs/safetensors/index"), ref("vLLM Conserving Memory", "https://docs.vllm.ai/en/v0.11.2/configuration/conserving_memory/")],
};

engineSystemTeaching["batch-executor"] = {
  intro: ["调度器决定本轮推进哪些请求，但模型需要规则的张量输入，多个设备还需要协调执行职责。Executor、Worker 和 Model Runner 是组织这些工作的软件角色；它们不是三种不同的数学模型。", "理解执行器的关键是追踪一次批次：变长请求怎样装入张量，数据交给谁算，结果怎样回到原请求。"],
  prerequisites: [pre("Batch", "共同组织执行的一组样本或位置。批处理可以提高资源利用，但必须保留每条请求的边界和身份。", "vllm-scheduler"), pre("Padding / Packing", "Padding 把短序列补到统一长度；Packing 把有效位置紧凑放在一起，并用长度、偏移等信息保留边界。"), pre("Worker", "承担实际设备执行职责的工作单元，常由进程承载。具体进程与设备映射取决于执行后端。")],
  chapters: {
    pack: section("紧凑张量需要额外保存请求边界",
      p("A、B 两条请求本轮分别有 3、1 个有效位置时，可以放进长度为 4 的紧凑数组。累计偏移 0、3、4 记录两段范围：A 是 [0,3)，B 是 [3,4)。方括号与圆括号表示包含起点、不包含终点。若都补齐到最长的 3 个位置，则需要 2×3=6 个槽。"),
      p("紧凑拼接节省无效补齐位置，但并不把两条请求变成一条长序列。注意力仍需使用各自的上下文、Mask（允许哪些位置参与计算的规则）和 KV 映射；丢失边界就可能让不同请求相互读取。"),
      fig("图中固定 A3、B1 的顺序，边界为 [0,3,4]。请求身份与请求内位置都被保留；紧凑数组的行号只是本轮存放位置。")),
    workers: section("软件角色分别负责协调、设备工作与输入组织",
      table("按职责理解名称", ["角色", "主要负责", "不应直接等同"], [["Executor", "协调一次模型执行所涉及的工作单元", "单个 GPU Kernel"], ["Worker", "承载某设备或进程侧的模型与执行工作", "完整独立模型副本"], ["Model Runner", "准备输入、调用模型并组织执行结果", "只做请求排队的 Scheduler"]]),
      p("在张量并行 TP 中，每个 Worker 可能只持有一部分权重与计算结果；在数据并行 DP 中，不同 Worker 组可能持有完整副本并服务不同请求。不能仅凭 Worker 数量判断并行方式。名称与类边界会随框架版本变化，应回到实际职责核对。")),
    return: section("从输出行恢复请求身份与生成状态",
      p("计算结果必须通过输入时保留的映射回到请求。对于生成，需要找出各请求当前应采样的位置；输入还没处理完的请求，不应把中间位置的输出误当成用户的新回答。"),
      p("如果为了执行效率重排了批次，返回时要使用逆映射或稳定 ID。随后更新已计算位置、采样结果和停止状态。这一步把设备张量重新接回服务层，错误不会仅表现为速度变慢，还可能把 A 的结果送给 B。")),
  },
  closing: ["执行器把调度决定落实为张量和设备协作，结果映射又把张量接回请求。批次能重排，身份和边界不能丢。"], references: [VLLM, CUDA],
};

engineSystemTeaching["kv-preemption"] = {
  intro: ["活跃请求的历史越来越长，KV 空间可能在计算预算用完前就耗尽。此时引擎需要决定谁继续、谁等待，以及是否释放部分请求状态。抢占让出资源，也会产生恢复成本。", "本课把‘释放块’与‘保留请求可以恢复的信息’区分开，避免把缓存紧张理解成简单加一个排队标志。"],
  prerequisites: [pre("物理 KV 块", "真实占据缓存容量的分配单位；多个逻辑块引用可能指向同一物理块。", "kv-cache"), pre("抢占", "暂时停止某条请求继续使用资源，把资源让给其它工作。请求可以仍然存在，并等待之后恢复。"), pre("重计算", "丢掉某些中间状态后，重新执行相应前缀来恢复状态；它节省保留空间，却需要重复计算。")],
  chapters: {
    capacity: section("先数真实物理占用，再判断还能分多少",
      p("将所有请求的逻辑块数直接相加，可能重复计算共享前缀；只数全局空闲块，又可能忽略请求已有尾块中的空槽。需要同时知道物理块的占用、共享引用和本轮新增需求。"),
      p("若新增位置跨过尾块边界，就需要新的物理块。分配失败是状态空间不足的证据，并不自动说明计算单元已满。先确认哪个资源挡住了请求，才有理由选择减小并发、限制长度或抢占。")),
    evict: section("抢占能释放哪些状态，要看其使用关系",
      p("停止继续调度某条请求后，只有不再被在途操作使用的专有块才可安全让出。共享前缀仍被其它请求引用时，不能因为这条请求被抢占就整体回收。释放的是特定物理资源，不是抽象地删除一个请求名字。"),
      p("采用重计算恢复时，还要保留重建所需的 Token 序列和请求配置；采用换出策略时，则会引入搬运和外部存储。不同引擎、版本和配置使用的策略可以不同，应明确本次观察的是哪条路径。")),
    resume: section("恢复把先前省下的空间变成后续工作",
      p("重计算恢复需要重新执行相应已知前缀，建立丢失的 KV，之后才能继续生成。已知 Token 不代表其 KV 还在；把这些 Token 再送入模型，是恢复状态，而不是重新向用户输出同一段回答。"),
      p("因此频繁抢占可能形成重复工作，影响首个输出、生成间隔和吞吐。仅看到某次回收后更多请求进入执行，不足以证明整体更快；需要统计抢占频率、恢复量和完整请求延迟。")),
  },
  closing: ["抢占在当前容量与未来恢复成本之间取舍。正确实现要保留可恢复的信息并尊重引用和完成依赖，性能判断要把恢复工作算进去。"], references: [TUNING, PAGED],
};

engineSystemTeaching["async-engine"] = {
  intro: ["同步引擎经常按‘CPU 准备一轮，GPU 执行，CPU 等结果，再准备下一轮’推进。若下一轮的一部分准备并不依赖最终结果，就可以与当前 GPU 执行重叠，减少两侧交替等待。", "异步调度的难点是分清哪些信息已经确定、哪些只是预计会出现，以及什么时候才允许使用真实结果。提前准备不能破坏自回归生成的数据依赖。"],
  prerequisites: [pre("依赖", "工作 B 要使用工作 A 的结果时，A 必须先满足完成和可见性条件；与 A 无关的准备则可能提前进行。", "host-runtime"), pre("占位", "先保留将来结果的位置或数量信息，但其中的实际 Token 值还未确定。占位是组织工具，不是模型答案。"), pre("关键路径", "决定最终完成时刻的一串先后依赖。把不在关键路径上的工作隐藏起来，未必改善最终时间。")],
  chapters: {
    overlap: section("提前做已经不需要等待的准备",
      p("某些请求身份、缓冲位置和结构信息可以提前组织，而具体 Token 值、停止判断或本轮真实输出仍需等待设备结果。异步设计应把这两类信息分开，使可提前的工作与 GPU 执行重叠。"),
      p("同步流程可以把一轮主机准备时间与设备执行时间相加；理想流水的稳态节拍则可能接近两者较大的一项。但启动、排空和有依赖的处理仍存在，不能把整个请求直接除以两倍。"),
      fig("图中 CPU 独立准备每轮 2 拍，GPU 执行每轮 4 拍，并忽略绑定与传输成本。三轮从启动到全部完成共 14 拍；4 拍是填充后相邻轮的稳态间隔，不是三轮总耗时。提前的是独立元数据准备，下一轮真实 Token 仍需等待前轮结果。")),
    placeholder: section("位置可以先占好，真实结果仍需正确交付",
      p("占位表示‘这个请求预计在这里有下一位置’，并不提供该位置的真实 Token。消费者若需要实际数值，必须等待结果写入并满足相应完成依赖，或使用实现明确支持的安全设备侧衔接。"),
      p("提前安排还会遇到请求结束、取消或实际输出数量变化。系统必须修正预计状态，防止把不存在的位置记成已经完成。以预计数量减少主机等待，与声称未来结果已经算出，是完全不同的事情。")),
    critical: section("重叠收益取决于较慢阶段和不可隐藏部分",
      formula("两阶段理想流水的稳态节拍下界", "<mrow><msub><mi>T</mi><mtext>steady</mtext></msub><mo>≥</mo><mi>max</mi><mo>(</mo><msub><mi>T</mi><mtext>host</mtext></msub><mo>,</mo><msub><mi>T</mi><mtext>device</mtext></msub><mo>)</mo></mrow>", [["T_host", "每轮可流水的主机阶段工作时间"], ["T_device", "每轮设备阶段工作时间"], ["T_steady", "稳定流水后连续完成轮次的间隔"]], "这个下界假定相应阶段可以重叠且没有额外资源争用。不可提前的处理、同步、通信和资源共享会增加实际间隔。"),
      p("若主机准备已经很短，继续隐藏它的空间有限；若主机阶段变成瓶颈，GPU 仍会等待。应比较真实时间线和完整请求指标，确认少掉的是等待而非遗漏的工作。")),
  },
  closing: ["异步引擎让已确定的信息提前流动，同时保留真实结果的依赖边界。理解它需要跟踪信息何时确定，而不只是观察两条时间条是否重叠。"], references: [VLLM, CUDA, ref("vLLM V1 Scheduler 源码接口（v0.11.2）", "https://docs.vllm.ai/en/v0.11.2/api/vllm/v1/core/sched/scheduler/")],
};

engineSystemTeaching["backend-dispatch"] = {
  intro: ["一项模型计算往往有多个实现：某些擅长特定数据类型，某些支持更长序列或特殊布局，另一些作为通用回退。派发就是在当前条件下选择一条合法执行路径，再在合法候选中考虑性能。"],
  prerequisites: [pre("后端 / Kernel", "后端提供一类计算的实现，Kernel 是其中在设备上执行的具体并行函数。前端算子名称不唯一决定 Kernel。", "compiler-lowering"), pre("Shape / dtype / layout", "分别是张量各轴长度、元素数值格式和实际排列/归属方式。支持某个算子不代表支持它的所有组合。", "tensor-address"), pre("Fallback", "优先路径不适用时选择另一个合法实现。它可能保证功能，但性能和资源行为会不同。")],
  chapters: {
    matrix: section("可用实现需要同时满足所有必要条件",
      p("先列出模型要求的数学语义，例如因果或滑窗注意力、KV 组织和量化方式；再核对后端支持的数据类型、形状、布局、硬件架构与执行模式。满足一项条件不能代替其它条件。"),
      table("派发前需要核对的不同层次", ["层次", "示例问题"], [["数学语义", "是否正确支持当前 Mask（允许参与计算的位置规则）、位置和状态更新"], ["数据表示", "元素类型 dtype、每头向量长度、地址步长 Stride、量化缩放 Scale 是否满足要求"], ["设备能力", "编译目标和指令是否被当前 GPU 支持"], ["运行方式", "当前图重放、并行模式和缓冲约定是否兼容"]]),
      p("支持矩阵用于排除不合法候选；即使候选合法，也还需要在当前规模和负载下测性能。‘能运行’与‘最合适’是两步判断。")),
    selection: section("配置选择之后还要核实实际路径",
      p("框架可能自动选择后端，也可能接受用户偏好并在条件不满足时回退。只看启动参数或安装的库名，不能证明这次计算真正用了它。应结合选择日志、执行追踪或明确的派发信息核对。"),
      p("比较优化前后时，先确认两边数学语义和数值精度一致，再记录实际 Kernel、转换步骤和回退。否则某次明显变慢可能来自条件变化，而不是同一 Kernel 的实现退化。")),
  },
  closing: ["派发是条件判断：先保证语义与表示合法，再比较实际执行路径。把条件和选择结果记录下来，才能解释同一个 API 为什么会有不同表现。"], references: [VLLM, CUDA, ref("vLLM Attention Backends", "https://docs.vllm.ai/en/v0.11.2/api/vllm/attention/backends/abstract/")],
};

engineSystemTeaching["admission-backpressure"] = {
  intro: ["请求到达速度可能超过系统能持续完成的速度。如果一直接收，队列会越来越长；更多等待请求不会自动变成更多 GPU 算力。接纳控制和背压负责让进入系统的工作量与可服务能力相匹配。", "这些机制还决定不同用户如何分享资源，因此需要同时考虑延迟、拒绝、重试和公平性，而不只是把队列长度调大。"],
  prerequisites: [pre("到达率与服务率", "分别表示单位时间进入和可完成的请求量。比较时需要固定请求工作量分布，长短不同的请求不能简单当作等成本。", "serving-slo"), pre("背压", "下游忙不过来时，让上游减慢、等待或停止继续送入的反馈机制。"), pre("配额与隔离", "配额限制某类使用者占用的资源；隔离减少彼此干扰。不同实现能提供的保证程度不同。")],
  chapters: {
    queue: section("持续积压意味着到达的工作没有被及时消化",
      formula("按时间窗口记录队列变化", "<mrow><msub><mi>Q</mi><mrow><mi>k</mi><mo>+</mo><mn>1</mn></mrow></msub><mo>=</mo><mi>max</mi><mo>(</mo><mn>0</mn><mo>,</mo><msub><mi>Q</mi><mi>k</mi></msub><mo>+</mo><msub><mi>A</mi><mi>k</mi></msub><mo>−</mo><msub><mi>S</mi><mi>k</mi></msub><mo>)</mo></mrow>", [["Qₖ", "窗口开始时待处理请求数"], ["Aₖ", "本窗口新接纳的请求数"], ["Sₖ", "本窗口用于消化队列的服务数量，按同一计数口径"], ["k", "离散时间窗口编号"]], "这是简化的队列账本。若进入的工作长期多于可消化工作，增大队列只能容纳更多等待，无法创造服务能力。"),
      p("请求数只是第一层观察。输入长度、输出长度和缓存占用不同，会使相同队列长度代表不同负载。服务控制还应结合工作量估计与实际等待时间。")),
    policy: section("满载时明确选择等待、拒绝或限速",
      table("不同策略承担不同代价", ["策略", "可能保护的目标", "需要处理的后果"], [["有界排队", "避免无限积压和内存增长", "队列满时要有明确拒绝或重试语义"], ["上游限速/背压", "减少持续进入的压力", "上游必须能观察并遵守反馈"], ["请求超时与取消", "结束已失去价值的等待", "取消后仍需安全处理在途工作与资源"], ["扩容或降低单请求成本", "提高可持续服务能力", "扩容启动、模型装载和通信成本仍存在"]]),
      p("拒绝不是自动失败的设计，有时它保护已接纳请求的服务目标。关键是把错误返回、重试间隔和客户端行为一起设计；立即无节制重试会把压力重新放大。")),
    fairness: section("公平需要选定资源和时间尺度",
      p("按请求数平分资源，可能让短请求与长请求获得很不一样的计算和显存份额。按 Token 数也只是近似，因为长上下文位置的实际成本可能不同。应说明公平针对用户、请求、计算份额还是响应目标。"),
      p("多个逻辑队列可以控制排序，却不必然隔离共享缓存、带宽或计算单元。若需要严格租户隔离，应结合执行资源与内存边界；本课的队列例子只说明调度与反馈，不能宣称已有完整多租户安全隔离。")),
  },
  closing: ["系统容量有限时，接纳策略决定哪些工作进入、如何等待和何时拒绝。目标是在给定负载下保持可用响应与明确公平规则，而不是无限积累请求。"], references: [VLLM, TUNING, ref("Google SRE：过载处理", "https://sre.google/sre-book/handling-overload/")],
};

engineSystemTeaching["process-threads"] = {
  intro: ["推理系统常由多个进程和线程组成：有的接收请求，有的准备输入，有的提交设备工作。理解它们是否共享数据、为什么等待以及怎样同步，是解释主机瓶颈和并发错误的基础。", "先把地址空间与执行状态分开：进程规定资源和地址的上下文，线程是执行指令的主体。多个线程可以共享数据，但共享本身不保证正确协作。"],
  prerequisites: [pre("地址空间", "进程用来解释虚拟地址的映射环境。同一个数字地址在不同进程中，可能映射到完全不同的物理对象。"), pre("执行状态", "包括当前执行位置、寄存器和栈等。一个线程被暂停后，需要保存这些信息才能继续。"), pre("竞态", "多个执行者以未正确协调的次序访问共享状态，使结果依赖执行交错。至少一方写入时尤其需要核对同步规则。")],
  chapters: {
    spaces: section("进程隔离地址解释，线程共享进程内存",
      p("同一进程中的线程共享全局数据和堆等地址空间，各自有执行状态和栈。不同进程通常拥有各自地址空间；通过明确的共享内存机制，才可能把同一物理区域映射给多个进程。"),
      p("因此，把一个指针数字发给另一个进程，并不能让对方访问原对象。需要传递可建立共享映射的句柄、数据本身或其它进程间通信协议。判断共享关系，应追踪底层对象与映射，而不是比较地址打印值。")),
    states: section("有工作不等于正在占用 CPU",
      table("线程的三类基本执行状态", ["状态", "含义", "常见下一步"], [["运行", "当前正在 CPU 上执行", "继续、被抢占或等待"], ["就绪", "具备运行条件但尚未获得 CPU", "由系统调度执行"], ["阻塞/等待", "在等锁、I/O、事件等条件", "条件满足后回到就绪"]]),
      p("主机线程在等待 GPU Event 时可能不消耗很多 CPU，却仍位于请求关键路径。CPU 使用率不高，不能直接推出主机调度没有瓶颈；也可能是一个依赖把后续工作全部挡住。")),
    race: section("一次加一在执行上可能是读、改、写三步",
      p("两个线程都把共享计数器加一：若它们先后都读到 0，再各自在本地算出 1，最后都写入 1，就丢掉了一次更新。源代码中的一个表达式，不保证对应一次不可分割的共享状态操作。"),
      table("一种会丢失更新的交错", ["时刻", "线程 A", "线程 B", "共享值"], [["1", "读到 0", "", "0"], ["2", "", "读到 0", "0"], ["3", "写入 1", "", "1"], ["4", "", "写入 1", "1"]]),
      p("这个例子说明为什么要使用适当的原子操作或锁。实际语言内存模型还规定哪些未同步读写属于未定义行为，不能依赖某次机器运行恰好没有出错。")),
    lock: section("同步保护共享关系，而不是装饰一条语句",
      p("锁让一段临界区在约定下由一个执行者操作；原子操作为特定访问提供不可分割等语义。若需要同时维护‘队列内容与长度一致’，只把长度加减做成原子，并不能自动保护整个不变量。"),
      p("同步范围过小可能破坏关系，过大可能阻塞无关工作。先写清共享状态应保持什么条件、谁能访问、何时可见，再选择锁、原子或消息传递。线程数量增加能否提升吞吐，还取决于这部分工作是否可并行。")),
  },
  closing: ["并发程序需要同时理解对象归属、线程进度和共享状态不变量。地址相同、代码相邻和线程更多，都不能替代明确的同步关系。"], references: [ref("Linux pthreads(7)", "https://man7.org/linux/man-pages/man7/pthreads.7.html"), ref("Linux pthread_mutex_lock(3)", "https://man7.org/linux/man-pages/man3/pthread_mutex_lock.3p.html"), ref("Linux mmap(2)", "https://man7.org/linux/man-pages/man2/mmap.2.html")],
};

engineSystemTeaching["host-memory-pages"] = {
  intro: ["CPU 程序常把一个数组看成连续地址，设备搬运却还受到内存页、固定驻留和物理拓扑影响。理解这些条件，才能解释为什么相同字节数的 Host-to-Device 传输会走不同路径、产生不同等待。"],
  prerequisites: [pre("虚拟地址与物理页", "虚拟地址是程序使用的地址；操作系统以页为单位映射到物理内存。虚拟连续不要求物理页连续。"), pre("DMA", "Direct Memory Access，设备或传输引擎直接访问相应内存来搬运数据，CPU 不必逐字节执行拷贝指令。地址映射与生命周期仍必须有效。"), pre("NUMA", "非一致内存访问：不同 CPU 与内存节点之间的距离和通路不同，访问成本可能随位置改变。")],
  chapters: {
    pages: section("一段连续虚拟数组可以落在多个物理页上",
      p("程序使用基址加偏移访问数组，操作系统的页映射把每个虚拟页连接到实际物理页。这允许灵活分配内存，也意味着仅从虚拟地址连续性无法推断物理摆放或到设备的传输路径。"),
      p("映射建立、页首次触碰和驻留状态都可能影响首次访问。性能分析应区分数组的逻辑大小、实际驻留页和访问发生的节点；不要把文件大小、虚拟地址范围与当前物理内存占用当作同一指标。"),
      fig("按页追踪虚拟顺序与物理页位置。这个图解释映射关系，不规定操作系统每次都采用相同物理排列。")),
    pin: section("固定主机页，为相应异步传输提供条件",
      p("Pinned / Page-locked Memory 指按接口约定固定驻留的主机内存。与普通可分页内存相比，它能为相应 DMA 和异步传输路径提供稳定条件，避免运行时必须先暂存到合适的缓冲。它仍然是主机内存，并不会变成 GPU HBM。"),
      p("在常见离散 CUDA 设备的主机传输与 Kernel 重叠路径中，需要页锁定主机内存，还要满足设备能力、队列和依赖条件。函数名带 Async 并不保证所有内存类型与调用组合都完全异步。固定太多主机页也会消耗系统资源，需按实际生命周期管理。")),
    numa: section("相同字节也可能经过不同物理距离",
      p("在多路 CPU 系统中，内存页可能位于某个 NUMA 节点，GPU 或 I/O 设备也连接在特定通路上。线程运行位置、页分配位置和设备连接位置共同决定访问是否需要跨节点。"),
      p("因此，先查看实际拓扑和内存分配，再测量对应路径。绑定 CPU 或内存节点是否有益，需要与数据生产者、GPU 连接和其它负载一起考虑；不能仅按 GPU 编号猜测最佳节点。")),
  },
  closing: ["主机数据搬运的前提不只是一根指针。页映射决定地址如何解释，固定驻留支持相应传输路径，NUMA 拓扑影响数据实际经过哪里。"], references: [CUDA, ref("Linux mmap(2)", "https://man7.org/linux/man-pages/man2/mmap.2.html"), ref("Linux numa(7)", "https://man7.org/linux/man-pages/man7/numa.7.html")],
};

engineSystemTeaching["cuda-context"] = {
  intro: ["CUDA Runtime 提供常用的设备管理、内存、Stream 和 Kernel 启动接口，Driver 层处理更底层的设备执行管理。Context（上下文）保存一组相关设备资源与状态，使一次调用知道自己在什么资源环境里工作。", "理解 Context 的价值在于资源归属：某块设备内存、某条 Stream 和某份加载代码属于怎样的执行环境，跨线程或跨进程使用时需要满足什么条件。"],
  prerequisites: [pre("进程与地址空间", "不同进程不能只凭相同指针数字访问同一对象，通常需要明确的共享或通信机制。", "process-threads"), pre("Stream", "CUDA 中组织设备工作顺序的队列。它属于相应设备执行环境，不是独立 GPU。", "runtime-graph"), pre("Driver", "连接用户态应用与设备能力的软件层；它与应用使用的 Runtime/库版本有兼容关系。", "deployment-compatibility")],
  chapters: {
    owners: section("资源必须在正确的设备与上下文中解释",
      p("创建分配、Stream 或加载设备代码时，会建立相应资源归属。后续调用需要使用合法的设备和上下文关系。Runtime 通常管理每设备的 primary context（主上下文），Driver API 还允许更显式的上下文控制；两类接口需要按文档规则配合。"),
      p("多个主机线程可以围绕同一设备提交工作，但仍要保证资源有效和必要同步。切换当前设备与创建一个全新模型副本不是同一个操作，也不能靠一个设备指针猜出当前所有执行状态。")),
    boundary: section("跨进程共享需要传递资源协议",
      p("进程 A 分配的 GPU 缓冲，不能把打印出的十六进制地址发给进程 B 就结束共享。B 需要通过合法机制获得可访问的映射，并知道尺寸、数据类型、布局和生命周期。"),
      p("CUDA IPC（进程间通信）等机制使用可导出和导入的句柄建立相应关系；真实可用条件取决于资源类型、设备和平台。共享后也仍需同步，确保生产者完成写入、消费者完成读取，再释放资源。")),
  },
  closing: ["Runtime 与 Driver 是软件接口层次，Context 是资源和状态环境。正确使用设备内存需要同时满足地址映射、上下文归属和完成依赖。"], references: [CUDA, ref("CUDA Driver API：Context Management", "https://docs.nvidia.com/cuda/cuda-driver-api/group__CUDA__CTX.html")],
};

engineSystemTeaching["tensor-parallel"] = {
  intro: ["张量并行 TP 把同一次模型计算拆给多张卡；数据并行 DP 则用多个模型副本处理不同请求。理解两者，先沿一个矩阵乘法看切分轴如何决定局部结果，再看模型副本与请求如何分配。"],
  prerequisites: [pre("矩阵乘法", "本课采用行向量 x 乘权重 W：x 的长度 K，W 的形状 K×N，输出长度 N。每个输出坐标沿 K 轴求和。", "gemm-tiling"), pre("切片与拼接", "切片取得某些坐标，拼接按约定顺序把不同坐标组合起来；它们不进行逐坐标求和。"), pre("归约", "把同一结果坐标的多个贡献按求和等操作合并。", "multi-gpu")],
  chapters: {
    column: section("沿输出轴切分，各卡得到不同输出坐标",
      p("把 W 的列分成 W₀ 与 W₁，两张卡都读取完整 x，各自计算一部分输出。因为列代表输出特征，局部结果拥有不同坐标，需要完整输出时把它们按顺序拼起来。"),
      formula("按列切分的结果关系", "<mrow><mi>W</mi><mo>=</mo><mo>[</mo><msub><mi>W</mi><mn>0</mn></msub><mo>,</mo><msub><mi>W</mi><mn>1</mn></msub><mo>]</mo><mo>⇒</mo><mi>xW</mi><mo>=</mo><mo>[</mo><mi>x</mi><msub><mi>W</mi><mn>0</mn></msub><mo>,</mo><mi>x</mi><msub><mi>W</mi><mn>1</mn></msub><mo>]</mo></mrow>", [["x", "长度 K 的输入行向量"], ["W₀ / W₁", "W 的不同输出列分片，具有相同输入轴 K"], ["[ , ]", "沿输出坐标拼接"]], "每个分片都完成自己输出坐标的全部求和。若下一层可以继续消费分片，未必立刻需要完整拼接。")),
    row: section("沿输入归约轴切分，各卡提供部分和",
      formula("按输入轴切分的结果关系", "<mrow><mi>xW</mi><mo>=</mo><msub><mi>x</mi><mn>0</mn></msub><msub><mi>W</mi><mn>0</mn></msub><mo>+</mo><msub><mi>x</mi><mn>1</mn></msub><msub><mi>W</mi><mn>1</mn></msub></mrow>", [["x₀ / x₁", "输入向量沿 K 轴的两个互补片段"], ["W₀ / W₁", "与对应输入片段相乘的权重行"], ["+", "对相同输出坐标相加"]], "这里切开的是每个输出元素内部的求和项，因此局部输出形状相同，但只是部分贡献。", ["x=[1,2]，W 的两行分别是 [1,2]、[3,4]。", "两张卡分别得到 [1,2] 与 [6,8]，求和才得到完整输出 [7,10]。", "若沿列切分则会得到 [7] 与 [10]；把它们求和成 [17] 就改变了输出含义。"]),
      p("列切分与行切分可以在相邻层之间配合，减少不必要的数据恢复。完整模型中的选择还要尊重非线性、归一化及注意力头等依赖。")),
    data: section("DP 用模型副本分担不同请求",
      p("推理数据并行把不同请求送到不同模型副本。每个副本可以独立产生自己请求的输出，因此不会仅因 DP 就把这些输出逐元素求和。一个副本内部仍可以使用 TP，或把连续层段分给不同设备的流水并行 PP，让不同并行方式在不同层次组合。"),
      table("比较资源职责", ["方式", "模型权重", "请求计算", "主要取舍"], [["TP", "同一模型分片", "多卡合作处理同一次计算", "降低每卡权重压力，增加计算间通信"], ["DP", "多个模型副本", "副本分担不同请求", "扩展并发服务能力，同时复制模型存储"]]),
      p("训练里的 DP 还涉及梯度同步；本课讨论推理请求分配，不把训练通信规则无条件套到推理输出上。")),
  },
  closing: ["先看切分的是输出坐标还是求和项，就能判断需要拼接还是归约；再看是否复制模型、分配不同请求，就能分清 TP 与 DP 的系统职责。"], references: [ref("Megatron-LM", "https://arxiv.org/abs/1909.08053"), NCCL, TUNING],
};

engineSystemTeaching["pipeline-parallel"] = {
  intro: ["流水并行 PP 把模型的连续层段放到不同设备。同一条输入仍要依次经过这些层段，不能跳过依赖；并行机会来自不同小批次同时处在不同层段。", "它与 PD 分离都可能跨设备搬运数据，但切分边界不同。先跟踪一个批次走过层段，再看多个批次如何填满流水。"],
  prerequisites: [pre("Stage", "一个设备或执行组负责的一段连续模型层。"), pre("Microbatch", "为流水交叠而拆出的较小批次；它仍有稳定身份和完整的层间依赖。"), pre("Activation", "某层计算产生、供后续层使用的中间表示，通常是带有批次、位置和隐藏维的张量。", "transformer-layer")],
  chapters: {
    wave: section("一个批次串行经过层段，多个批次交叠",
      p("设两段计算各需要一拍。批次 A 在第 1 拍经过段 0，第 2 拍经过段 1；这时批次 B 可以进入段 0。B、C 跟随 A 前进，形成不同批次的交叠，而不是 A 自己同时完成两段。"),
      formula("理想等长前向流水的完成时间", "<mrow><mi>T</mi><mo>=</mo><mo>(</mo><mi>m</mi><mo>+</mo><mi>p</mi><mo>−</mo><mn>1</mn><mo>)</mo><mi>t</mi></mrow>", [["m", "Microbatch 数量"], ["p", "层段数量"], ["t", "每段处理一个 Microbatch 的相同时间"], ["T", "从第一批开始到最后一批完成的时间"]], "第一批需要 p 拍走完全程，后续每拍完成一批，所以总共 p+(m−1) 拍。假定忽略传输、各段等长且只做前向。", ["p=2、m=3、t=1 拍时，共 4 拍完成；逐批完全串行执行需要 6 拍。", "开头填充和结尾排空时仍有部分设备空闲，这些没有有效工作的时段称为 Bubble（流水空泡）。"])),
    boundary: section("PP 交接层边界激活，PD 交接请求阶段状态",
      p("PP 的下一段要接着执行后续层，因此跨段交付的是相应层边界激活及必要元数据。各段处理自己负责的层，所需本地历史状态按实现分配。"),
      p("PD 则把输入处理与后续生成分开，D 端需要可用于继续生成的历史状态，常涉及跨层 KV 的交接。两者可以组合，但不是同一名称的不同写法；分析通信量前必须先明确搬运对象。")),
    imbalance: section("最慢层段限制稳态节拍",
      p("当一段处理一批需要 2 拍，另一段只需 1 拍时，较快段可能等待前后依赖。增加 Microbatch 数能摊薄起止空泡，却不能把最慢段的工作变短；通信也可能成为新的慢阶段。"),
      p("分段不能只数层数。不同层的计算、显存、通信和输入形状可能不同，生成过程还会受跨步依赖限制。需要用实际负载测各段时间，再决定分配和流水组织。")),
  },
  closing: ["流水并行用不同批次占据不同层段来利用多设备。它的收益受填充/排空、段不平衡、传输和真实依赖限制，理想公式只给出清楚的参照。"], references: [ref("GPipe", "https://arxiv.org/abs/1811.06965"), TUNING, NCCL],
};

engineSystemTeaching["collective-topology"] = {
  intro: ["AllReduce 的数学要求很简单：各卡对同一组坐标的贡献相加，并把结果交给每张卡。数学要求没有指定数据必须走哪条链路；Ring（环形）只是完成这件事的一种组织方式。", "这门课把结果语义、算法通信量、物理传输时间分开。这样看到‘每卡发送了多少字节’时，就知道它解释了什么，还不能说明什么。"],
  prerequisites: [pre("Rank", "参与一次集合通信的逻辑成员编号。编号决定某些分片的顺序；它不自动等于物理 GPU 插槽号。"), pre("归约与拼接", "归约把同一输出坐标的多个贡献相加；拼接把不同坐标按顺序排在一起。两者不能互换。", "multi-gpu"), pre("链路", "两个设备之间搬运数据的物理或逻辑通路，可能经过交换机或共享上游带宽。")],
  chapters: {
    ring: section("先形成完整分片，再让所有卡拿齐结果",
      p("假设 p 张卡各持有同样形状的输入，把每张输入切成 p 个等长分片。ReduceScatter 阶段让分片沿环传递：每经过一张卡，就加入该卡对相同坐标的贡献。经过 p−1 轮，完整结果的不同分片分别留在各卡。"),
      p("此时每张卡只拿到完整结果的一部分。接着 AllGather 阶段只转发已经完成归约的分片，不再重复相加；再经过 p−1 轮，每张卡拿齐全部分片。把这两个阶段连起来，才满足 AllReduce 的输出要求。"),
      table("用两张卡检查结果含义", ["阶段", "卡 0", "卡 1"], [["输入，各有两个坐标", "[1, 2]", "[10, 20]"], ["ReduceScatter 后，各保留一个已求和坐标", "[11]", "[22]"], ["AllGather 后，按坐标恢复", "[11, 22]", "[11, 22]"]]),
      note("真实通信库可以使用树形、多个环或其他算法。本节的环形过程解释一种实现，不代表 NCCL 的每一次调用都按这条路线执行。")),
    volume: section("每轮发送一个分片，由轮数得到通信量",
      formula("等分环形 AllReduce 的每 Rank 发送字节数", "<mrow><msub><mi>V</mi><mtext>send</mtext></msub><mo>=</mo><mn>2</mn><mo>(</mo><mi>p</mi><mo>−</mo><mn>1</mn><mo>)</mo><mfrac><mi>N</mi><mi>p</mi></mfrac></mrow>", [["N", "每张卡参与 AllReduce 的输入总大小，单位 byte"], ["p", "参与通信的 Rank 数量"], ["N/p", "均匀切分后一个分片的字节数"], ["Vsend", "单张卡在整个操作中发出的字节数，不包含接收量"]], "两个阶段各有 p−1 轮，每轮每张卡发出 N/p 字节，因此直接相乘。等长分片、理想环形算法是这个计数的前提。", ["p=4、N=1 MiB 时，每阶段发送 3×0.25=0.75 MiB，合计每卡发送 1.5 MiB。", "接收量也为 1.5 MiB；如果把收与发相加，应明确写成 3 MiB，不能悄悄改变通信量口径。", "把所有 Rank 的发送量相加得到 6 MiB，这是全系统发送量，并不等于某一条物理链路上的负载。"]),
      p("NCCL Tests 的算法带宽与总线带宽采用不同归一化口径。比较测量值前要查清分子是什么；一个经过算法系数换算的带宽，不能直接解释成某一物理端口的实测吞吐。")),
    topology: section("相同的字节数可能经过不同的瓶颈",
      p("四张卡即使发送完全相同的字节，也可能因 GPU 间直连、PCIe 交换层级、跨机网络、链路共享或 Rank 映射不同而花费不同时间。环中一个较慢的传输阶段会阻碍依赖它的后续阶段；小消息时，每轮启动与同步开销也可能比传输本身更显著。"),
      table("把性能现象接回证据", ["观察", "先核对", "能支持的判断"], [["大消息吞吐偏低", "实际路由、各链路流量、共享竞争", "是否受某条路径的持续传输能力限制"], ["小消息耗时几乎不随大小变", "启动开销、轮次、同步边界", "固定开销是否占主导"], ["通信变快但整步没变快", "计算与通信时间线、最终等待点", "被优化部分是否在关键路径上"]]),
      p("能与计算重叠的通信不应在总时间中重复相加，也不能因此假定它完全免费：它可能竞争内存或执行资源。最终要回到实际依赖与时间线，说明哪些传输仍挡住下一步。")),
  },
  closing: ["先确认所需结果，再选择算法并计算清楚口径，最后把字节映射到实际拓扑。通信量是性能分析的中间量，链路和依赖才决定它怎样进入总时间。"], references: [NCCL, ref("NCCL Tests：性能与带宽口径", "https://github.com/NVIDIA/nccl-tests/blob/master/doc/PERFORMANCE.md"), ref("NCCL：拓扑与算法环境参数", "https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html")],
};

engineSystemTeaching["deployment-compatibility"] = {
  intro: ["‘同一镜像在另一台机器启动失败’并不矛盾。镜像能固定应用程序和很多用户态依赖，却仍要使用宿主机的驱动、GPU 和设备接入条件。即使能启动，某个模型格式或算子后端也未必适用于这组环境。", "部署验收要证明一条实际路径：指定模型在指定软硬件组合上，使用预期数值格式与执行后端，完成正确的代表性请求。只看到服务进程存活，还没有走完这条路径。"],
  prerequisites: [pre("用户态库与驱动", "应用调用的 Runtime、算子库等运行在用户空间；GPU 驱动还负责与设备交互。二者的版本关系受到兼容规则约束。", "cuda-context"), pre("容器镜像", "保存应用文件、依赖和启动配置的文件系统快照。容器仍依赖宿主操作系统内核及被允许访问的设备。"), pre("后端", "实际执行一种算子或模型计算的实现。满足相同数学功能的后端可能要求不同硬件、类型和布局。", "backend-dispatch")],
  chapters: {
    layers: section("镜像固定文件环境，宿主提供设备环境",
      table("一份部署由哪些层共同构成", ["层", "典型内容", "镜像相同仍可能变化的部分"], [["应用与模型", "引擎代码、模型配置、权重、分词器", "外部挂载的模型版本、启动参数"], ["用户态执行依赖", "CUDA Runtime、算子库、Python 包", "运行时挂载或环境变量改变的加载路径"], ["宿主与设备", "内核驱动、GPU 架构、可见设备、互连", "驱动兼容性、硬件能力、容器设备接入"]]),
      p("NVIDIA Container Toolkit 负责把 GPU 设备及相关运行条件提供给容器，不能凭空给不支持某条指令的硬件增加该能力。更新镜像也不等于更新宿主内核驱动。"),
      p("CUDA 的小版本兼容、前向兼容都有适用条件和限制。应按实际驱动、Runtime、平台和 GPU 查官方矩阵；只比较版本字符串谁更大，推不出所有功能均可使用。")),
    matrix: section("按失败边界检查必要条件",
      p("把兼容性拆成可以验证的条件，会比一次升级全部组件更容易定位问题。先确认设备可访问，再确认程序能加载并执行最小运算，随后检查目标算子，最后运行完整模型；每一步对应不同的失败范围。"),
      table("逐层验收的证据", ["问题", "所需证据", "这一步还不能证明"], [["容器能否看到目标设备", "设备身份、驱动与权限记录", "目标内核能执行"], ["编译产物能否执行", "架构目标、加载结果、最小正确计算", "所有模型形状都被支持"], ["目标后端是否适用", "类型、布局、形状、功能约束及实际分派记录", "全负载下性能达标"], ["完整服务是否满足需求", "输出核对、代表性请求、并发与 SLO 测量", "没有测过的组合也成立"]]),
      p("例如，服务可以成功使用 BF16 路径，并不证明同一模型的 FP8 路径也受支持；FP8 是特定低精度浮点格式，还涉及缩放信息、权重格式及相应内核。验收必须覆盖实际将启用的路径。")),
    manifest: section("把成功条件记录成可复现的部署说明",
      p("一次成功验收的价值在于可重现。记录模型与分词器修订、镜像标识、宿主驱动、GPU 型号、引擎和算子库版本、权重与 KV 类型、并行配置以及关键启动参数，让后来的人能重新得到同一执行路径。"),
      p("测试记录还应包含输入/输出长度分布、并发或到达率、冷启动与稳态口径、正确性判据和性能阈值。‘启动成功’、‘输出正确’、‘后端符合预期’、‘性能达标’是四种证据，应分别保留结果。"),
      note("本课提供检查顺序和记录方法，不维护一份永久有效的版本数字表。具体兼容矩阵会更新，应把核验时所用的官方版本页面一并记入部署记录。")),
  },
  closing: ["可部署性来自模型、软件和设备条件的交集。把各层条件、实际执行路径与测试负载写清楚，下一次升级才知道需要重新验证哪些结论。"], references: [ref("CUDA Compatibility", "https://docs.nvidia.com/deploy/cuda-compatibility/"), ref("NVIDIA Container Toolkit 安装与前提", "https://docs.nvidia.com/datacenter/cloud-native/container-toolkit/latest/install-guide.html"), CUDA],
};

engineSystemTeaching["gpu-execution"] = {
  intro: ["写 CUDA 程序时，开发者描述的是很多逻辑线程及其合作关系；GPU 再把这些任务放到有限的执行资源上。线程编号说明‘负责哪份工作’，SM 编号说明‘这次在哪里执行’，这两个问题不能混为一谈。", "先把 Grid、Block、Warp、Lane 的关系建立起来，后续谈访存合并、同步、Warp 发射和 Occupancy 才有明确的对象。这里先用一维启动，避免让多维下标掩盖层次本身。"],
  prerequisites: [pre("Kernel", "一次被提交到 GPU 的程序入口；许多逻辑线程执行同一段代码，各自用编号决定处理的数据。"), pre("SM", "GPU 内的一组硬件执行资源，包含指令调度、运算与线程所需的片上存储。一个 GPU 通常有多个 SM。"), pre("寄存器与 Shared Memory", "寄存器保存线程自己的临时值；Shared Memory 是线程块内合作使用的显式存储区，需要按依赖正确同步。", "memory-route")],
  chapters: {
    indices: section("编号按任务层次分解，不代表物理位置",
      table("从启动到线程", ["层次", "中文理解", "与相邻层的关系"], [["Grid", "一次 Kernel 启动的全部线程块", "包含许多 Block"], ["Block / CTA", "可协作的一组线程", "CUDA 的 Block 对应 PTX 中的 CTA；每块独立编号"], ["Warp", "按线性线程编号分成的 32 线程组", "一个块可能包含多个 Warp，末尾可以不足 32 个有效线程"], ["Lane", "线程在 Warp 内的位置", "编号为 0 到 31"]]),
      formula("一维启动的逻辑索引", "<mrow><mi>g</mi><mo>=</mo><mi>b</mi><mi>B</mi><mo>+</mo><mi>t</mi><mo>,</mo><mspace width=\"1em\"/><mi>w</mi><mo>=</mo><mo>⌊</mo><mfrac><mi>t</mi><mn>32</mn></mfrac><mo>⌋</mo><mo>,</mo><mspace width=\"1em\"/><mi>l</mi><mo>=</mo><mi>t</mi><mo>mod</mo><mn>32</mn></mrow>", [["b", "Block 编号 blockIdx.x，从 0 开始"], ["B", "每 Block 的线程数 blockDim.x"], ["t", "Block 内线程编号 threadIdx.x"], ["g", "该一维 Grid 中的全局逻辑线程编号"], ["w / l", "Block 内 Warp 编号 / Warp 内 Lane 编号"]], "每个较早的 Block 占 B 个逻辑位置，再加块内偏移即可得到全局编号。Warp 与 Lane 则把块内编号按 32 分组。", ["B=64、b=1、t=5：g=69，块内 Warp 0、Lane 5。", "同一块的 t=37：g=101，块内 Warp 1、Lane 5。Lane 相同不意味着它们是同一个线程。"]),
      p("多维 Block 需要先按 CUDA 定义把 x、y、z 下标线性化，再分 Warp。本节的一维公式不能把三维 threadIdx.x 单独拿来当完整线程编号。")),
    scope: section("共享范围决定同步范围",
      p("同一个 Block 的线程可以通过该块的 Shared Memory 协作。一个线程把数据写好，不等于别的线程已经到了读取位置；需要相应的同步和内存可见性保证。普通的块级屏障 __syncthreads() 负责块内参与线程之间的同步，不会等待整个 Grid 的所有 Block。"),
      p("一个 Warp 的线程也不能因编号相邻就省略所有同步。现代架构允许线程在控制流中独立推进，依赖其他 Lane 写入的数据时，应使用符合参与线程集合的 Warp 同步或专用指令。跨 Block 合作则需要另一套合法协议。"),
      note("线程块集群、协作启动及分布式 Shared Memory 能扩展某些协作方式，但都有架构和启动条件。本课先建立普通 Block 的默认范围，不能把高级机制的能力自动套给所有 Kernel。")),
    schedule: section("硬件把逻辑 Block 放到可容纳它的 SM",
      p("Block 需要寄存器、Shared Memory 和线程槽等资源；只有资源允许时才能在 SM 上驻留。驻留后，硬件从相应 Warp 中选择可以执行的指令。逻辑上有很多线程，不意味着这些线程都在同一时刻计算。"),
      p("普通 CUDA 程序不应依赖 Block 的启动先后或固定的 Block→SM 对应关系。某个 Block 等待另一个尚未获得资源的 Block，若没有受支持的全局同步机制，可能无法取得进展。因此算法要尊重执行模型，而不能把图上画出的排列当成执行承诺。"),
      p("这也解释了两个不同的优化问题：工作量是否产生足够多的 Block，让整个 GPU 有事可做；每个 Block 的资源需求是否允许足够的 Warp 驻留。前者是任务分解，后者才进入 Occupancy 分析。")),
  },
  closing: ["Grid、Block、Warp、Lane 描述逻辑任务组织；SM 描述硬件执行位置。先确定数据由谁处理、谁与谁共享和同步，再讨论这些任务怎样占用硬件。"], references: [CUDA, BEST],
};

engineSystemTeaching["shared-bank"] = {
  intro: ["Shared Memory 在片上，但同时来的访问仍要通过有限的存储 Bank。Bank 可以理解为能并行服务的存储分区：把请求分散到不同 Bank，通常比让不同地址挤在同一 Bank 更容易并行处理。", "判断冲突不能只看线程编号或数组画得是否整齐，要先算出这一条指令访问的实际地址，再检查它们如何落到 Bank。本课先固定 32 位标量访问的基本模型。"],
  prerequisites: [pre("Warp", "由最多 32 个有效线程组成的执行组；本课查看同一个 Warp 的一条 Shared Memory 读指令。", "gpu-execution"), pre("元素地址与步长", "数组中相邻逻辑元素在内存里不一定相邻。步长说明下标增加 1 时，实际地址前进多少元素或字节。", "tensor-address"), pre("32 位字", "这里一个数据项占 4 字节；地址除以 4 后得到字地址，用于基本 Bank 映射计算。")],
  chapters: {
    map: section("把字节地址换成字地址，再看余数",
      formula("32 位标量、32 Bank 的基本映射", "<mrow><mi>bank</mi><mo>(</mo><mi>a</mi><mo>)</mo><mo>=</mo><mo>⌊</mo><mfrac><mi>a</mi><mn>4</mn></mfrac><mo>⌋</mo><mo>mod</mo><mn>32</mn></mrow>", [["a", "Shared Memory 字节地址，本节假定访问按 4 字节对齐"], ["⌊a/4⌋", "32 位字地址"], ["bank(a)", "Bank 编号，0 到 31"]], "相邻的 32 位字依次进入相邻 Bank，走过 32 个字后回到原 Bank。公式用于解释这一类访问的地址映射，不能直接替代向量化指令的完整事务分析。"),
      table("从具体地址看并行性", ["Lane i 读取", "字地址", "Bank", "基本判断"], [["连续元素 x[i]", "i", "i", "32 个 Lane 落在 32 个 Bank"], ["间隔 32 个元素 x[32i]", "32i", "0", "同一 Bank 的不同字，产生冲突"], ["同一个元素 x[0]", "0", "0", "同地址读取可广播，不能按 32 路冲突计算"]]),
      p("表中取首地址为 0 来简化余数。换一个对齐的首地址通常只是整体平移 Bank 编号；真正影响重复关系的是各 Lane 的相对地址。")),
    padding: section("加一列改变物理步长，逻辑矩阵仍是原矩阵",
      p("以行优先的 32×32 数组为例，同一列的相邻行相隔 32 个字。Lane i 读取第 i 行的同一列时，字地址相差 32，因而重复落在同一 Bank。把物理行宽扩成 33，逻辑上仍只使用 32 列，就改变了这个重复关系。"),
      formula("同列访问在加 Padding 前后的映射", "<mrow><mo>(</mo><mn>32</mn><mi>i</mi><mo>+</mo><mi>c</mi><mo>)</mo><mo>mod</mo><mn>32</mn><mo>=</mo><mi>c</mi><mo>,</mo><mspace width=\"1em\"/><mo>(</mo><mn>33</mn><mi>i</mi><mo>+</mo><mi>c</mi><mo>)</mo><mo>mod</mo><mn>32</mn><mo>=</mo><mo>(</mo><mi>i</mi><mo>+</mo><mi>c</mi><mo>)</mo><mo>mod</mo><mn>32</mn></mrow>", [["i", "Lane 同时对应所访问行，取 0…31"], ["c", "所有 Lane 读取的同一列，取 0…31"], ["32 / 33", "未填充 / 填充后的每行物理字数"]], "加一列后，每下一行，Bank 编号多前进 1，而不再回到同一位置。32 个 Lane 因而遍历所有 Bank。", ["额外空间为 32 行×1 字×4 byte=128 byte。", "消除这一种列访问冲突不代表所有访问都变快；仍需检查其他指令、总 Shared 用量和驻留限制。"]),
      p("Padding 是用少量存储空间换取更合适的地址关系。Swizzle 则通过重新排列地址达到类似目的；二者都应从实际消费者的访问模式反推，不能无条件给所有数组加一列。")),
    broadcast: section("同 Bank 与同地址是两个不同条件",
      p("如果 32 个 Lane 都读取同一个 32 位字，硬件可以把这个值广播给多个线程。它们共享的是同一数据项；若各 Lane 读取同一 Bank 的不同字，Bank 需要服务多个不同请求，才是基本模型中的冲突。"),
      p("读取广播也不能推广成‘多个线程同时写同一地址没关系’。并发写涉及谁的结果生效、是否存在数据竞争、是否需要原子操作等语义；没有合法协议时，较快地完成访问不代表结果正确。"),
      p("实际内核还会出现 64 位元素、向量指令、矩阵加载指令和事务拆分。分析时需要结合目标架构与指令，把一次 Warp 请求分解到实际服务单位，再用 Profiler 验证冲突，而不是把本课的一次取模结果当作任何指令的精确周期数。")),
  },
  closing: ["Bank 冲突来自同一次服务中，多个不同数据项争用同一 Bank。先算地址，再分清同字广播与不同字冲突，最后考虑 Padding、Swizzle 及它们增加的资源成本。"], references: [BEST, CUDA, NSIGHT],
};

engineSystemTeaching["occupancy-resources"] = {
  intro: ["一个 SM 可以同时保留多组尚未完成的线程状态，让某些 Warp 等待时，其他 Warp 继续推进。但这些状态占用寄存器、Shared Memory 和硬件槽位，不能无限增加。Occupancy 描述可以驻留多少 Warp，相对于设备上限占了多少。", "它首先是资源容量指标。要判断性能，还要看驻留的 Warp 中有多少具备执行条件、发射了多少指令，以及执行单元是否已经被有效使用。"],
  prerequisites: [pre("驻留", "一个 Block 已获得执行所需资源，其 Warp 状态留在 SM 上；即使当前等待依赖，也仍可能占着这些资源。", "gpu-execution"), pre("每线程寄存器数", "编译器为一个线程分配的寄存器资源。更多临时值可能减少数据重算或溢出，却也增加每个 Block 的资源需求。"), pre("Eligible Warp", "驻留且下一条指令的依赖等条件允许它被调度的 Warp；不是所有驻留 Warp 都处于这个状态。", "warp-issue")],
  chapters: {
    limits: section("每个资源给出一个可驻留 Block 上限",
      formula("忽略分配粒度时的资源容量模型", "<mrow><msub><mi>B</mi><mtext>resident</mtext></msub><mo>≤</mo><mi>min</mi><mo>(</mo><msub><mi>B</mi><mtext>hw</mtext></msub><mo>,</mo><mo>⌊</mo><mfrac><msub><mi>W</mi><mtext>SM</mtext></msub><msub><mi>W</mi><mtext>block</mtext></msub></mfrac><mo>⌋</mo><mo>,</mo><mo>⌊</mo><mfrac><msub><mi>R</mi><mtext>SM</mtext></msub><msub><mi>R</mi><mtext>block</mtext></msub></mfrac><mo>⌋</mo><mo>,</mo><mo>⌊</mo><mfrac><msub><mi>S</mi><mtext>SM</mtext></msub><msub><mi>S</mi><mtext>block</mtext></msub></mfrac><mo>⌋</mo><mo>)</mo></mrow>", [["Bresident / Bhw", "驻留 Block 数 / 硬件允许的 Block 数上限"], ["WSM / Wblock", "每 SM Warp 槽位数 / 每 Block 所需 Warp 数"], ["RSM / Rblock", "每 SM 寄存器容量 / 每 Block 寄存器需求，使用相同单位"], ["SSM / Sblock", "每 SM 可用 Shared Memory / 每 Block 所需 Shared 字节"]], "每种资源分别回答‘最多能装几块’，最紧的一项首先限制驻留。某项需求为 0 时应视为该项不构成限制，而不是做除零。实际分配有粒度、子分区和架构约束，因此这是推理模型，不是精确硬件计算器。"),
      p("由驻留 Block 数乘以每块 Warp 数，可得到静态容量下可驻留 Warp 数；再除以硬件 Warp 上限得到理论 Occupancy。实际执行时，工作量不足、起止阶段或不同 Block 完成时间，还会让观测到的平均驻留量低于理论上限。")),
    counter: section("资源数量连续增加，驻留数量会跨台阶变化",
      p("用一台专门为算术教学设定的虚构 SM：最多 4 个 Block、8 个 Warp、16,384 个 32 位寄存器、32 KiB Shared。每块 64 线程，即 2 个 Warp，并使用 8 KiB Shared。这些数字不是 B200 或其他真实 GPU 的规格。"),
      table("只改变每线程寄存器数", ["约束", "32 个寄存器/线程", "96 个寄存器/线程"], [["每块寄存器需求", "64×32=2,048", "64×96=6,144"], ["寄存器允许的 Block 数", "⌊16,384/2,048⌋=8", "⌊16,384/6,144⌋=2"], ["Warp / Shared / 硬件 Block 上限", "4 / 4 / 4", "4 / 4 / 4"], ["最终可驻留 Block / Warp", "4 / 8", "2 / 4"], ["理论 Occupancy", "8/8=100%", "4/8=50%"]]),
      p("左列寄存器还有余量，其他资源先到上限；右列寄存器成为最紧约束。增加一点资源不一定立即减小驻留数，越过装不下下一块的阈值才会下降。实际 GPU 的分配取整可能让这个阈值提前出现，应以编译信息和 Occupancy 工具核对。")),
    eligible: section("驻留是机会，准备好和发射才是推进",
      p("若 8 个驻留 Warp 都等待同一个阶段的数据，100% Occupancy 也可能没有可发射指令。反过来，较少 Warp 若各自有足够多互相独立的工作，也可能让目标执行单元持续繁忙。因此 Occupancy 提供隐藏等待的可能性，不直接等于利用率。"),
      p("减少寄存器使用有时能增加驻留，但过度压缩可能把临时值溢出到内存，带来新的访存。减少 Shared 用量也可能破坏数据复用。必须比较增加的调度机会与新增工作，最终看真实 Kernel 时间和相关瓶颈证据。"),
      table("三种指标回答不同问题", ["指标", "回答的问题"], [["Occupancy / Active Warps", "有多少 Warp 保留在 SM 上"], ["Eligible Warps", "当前有多少 Warp 满足发射条件"], ["Issued Instructions / 目标管线吞吐", "实际上推进了多少工作，是否用满目标资源"]])),
  },
  closing: ["用资源模型解释驻留上限，用依赖和发射状态解释执行进展，再用测量判断调整是否有效。优化目标是让所需工作更快完成，Occupancy 是其中一个诊断量。"], references: [BEST, CUDA, NSIGHT],
};

engineSystemTeaching["measurement-stability"] = {
  intro: ["优化前后差了几微秒，可能来自代码，也可能来自首次初始化、频率、功耗状态或测量边界。可信的性能结论首先要知道自己计时的是什么，并让重复实验真正比较同一种工作。", "这门课不追求把所有波动抹掉，而是区分可解释的阶段差异、正常分布和没有控制的条件。生产服务需要面对的波动，应如实进入结论。"],
  prerequisites: [pre("冷启动与稳态", "冷启动包含首次加载、初始化或编译等一次性工作；稳态是这些前置阶段完成后的重复运行。两者服务不同问题。"), pre("样本与分位数", "一次测量是一个样本。分位数描述排序后某一位置附近的延迟，例如 P99 对应约 99% 样本不超过的值；估计高分位需要足够样本。", "serving-slo"), pre("计时边界", "从哪个事件开始、到哪个事件结束。CPU 提交结束不一定意味着 GPU 执行结束。", "host-runtime")],
  chapters: {
    cold: section("先解释第一次额外做了什么",
      p("第一次运行可能包含模型读取、内存分配、模块加载、内核编译、算法选择或图构建。并非每个框架都会发生全部步骤，但只要存在这些工作，把首轮与后续轮混在一起就会改变统计含义。"),
      p("若研究稳定执行的 Kernel 成本，应明确完成了哪些预热、从何时采样，并使用覆盖目标设备工作的计时边界。若研究服务启动体验，则需要保留从启动到可用、直到首个有效输出的时间。不能因为首轮慢，就在用户关心冷启动时删掉它。"),
      table("两类问题对应两类记录", ["测量目标", "主要保留", "应说明"], [["首次请求体验", "加载、初始化、编译、首个输出等阶段", "缓存和进程是否从冷态开始"], ["稳定负载效率", "预热后的重复执行与持续资源状态", "预热终止条件、采样长度和负载"]])),
    distribution: section("平均值与中位数保留的信息不同",
      table("单位为毫秒的两组教学样本", ["样本组", "5 次观测", "平均值", "中位数", "最大值"], [["A", "10, 10, 10, 10, 10", "10", "10", "10"], ["B", "8, 8, 8, 14, 14", "10.4", "8", "14"]]),
      p("B 的中位数更小，说明排序中间的那次更快；但两次 14 ms 把平均值提高到 10.4 ms。若只报告中位数，就会隐藏这组样本里的慢请求；若只报告平均值，又会看不出三次较快、两次较慢的形状。"),
      p("这些只有 5 个数，是用来理解统计量的算例，不能据此可靠估计生产 P99。正式结论应报告样本数量、重复实验、分布或关键分位，并说明超时、错误和未完成请求的处理方法。"),
      p("所谓异常值也要有原因。若慢样本对应真实的争用或服务尾延迟，删除它会改变问题；若确定是测量错误，则应保留排除规则及证据，而不是以是否有利于优化结论为标准。")),
    conditions: section("用条件记录支持归因，用重复验证区分波动",
      p("GPU 频率会受功耗和温度条件影响，其他进程可能竞争设备或主机资源。记录 GPU 型号、驱动、功耗限制、频率与温度观测、并发进程、输入形状及计时方法，能帮助解释为什么相同代码得出不同时间。"),
      p("比较 A 与 B 时，可以重复多轮、交替或随机安排顺序，降低先后顺序与温度变化绑在一起的风险。保持相同有效工作和输出正确性，报告收益相对波动的大小；如果差异落在不稳定范围内，就应继续寻找证据，而不是把一次最快结果当成确定收益。"),
      p("观测到慢的时候温度也高，只是相关线索。要支持温度导致性能变化，还需结合频率限制原因、受控对照或时间线。Profiler 本身也可能改变执行方式和耗时，应把性能基准运行与诊断采集的条件分别记清。")),
  },
  closing: ["可信测量有明确边界、可解释的冷暖阶段、足够的重复样本和可追溯的条件。结论既要说明提升了什么，也要保留它适用的负载与不确定范围。"], references: [ref("NVIDIA SMI：频率、温度与功耗状态", "https://docs.nvidia.com/deploy/nvidia-smi/index.html"), NSIGHT, BEST],
};
